-- ===== private-estimate-publications-local.sql =====
-- LOCAL only. Explicit immutable estimate publication/real client response; NO sends or financial posting.
begin;
create table if not exists pro_private_estimate_publications(owner_id uuid not null references profiles(id) on delete cascade,id uuid not null,estimate_id uuid not null,client_id text not null,version integer not null check(version>0),estimate_revision integer not null check(estimate_revision>0),content jsonb not null check(jsonb_typeof(content)='object'),content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),created_at timestamptz not null default clock_timestamp(),primary key(id),unique(owner_id,estimate_id,version),foreign key(owner_id,estimate_id) references pro_private_estimates(owner_id,id) on delete cascade);
create table if not exists pro_private_estimate_publication_states(publication_id uuid primary key references pro_private_estimate_publications(id) on delete cascade,revision integer not null default 1 check(revision>0),status text not null check(status in('awaiting_claim','shared','changes_requested','accepted','declined','withdrawn','superseded')),recipient_id uuid,check(status not in('shared','changes_requested','accepted','declined') or recipient_id is not null));
create table if not exists pro_private_estimate_publication_invites(publication_id uuid primary key references pro_private_estimate_publications(id) on delete cascade,code_hash text not null unique check(code_hash~'^[a-f0-9]{64}$'),email text not null,expires_at timestamptz not null,claimed_by uuid,claimed_at timestamptz);
create table if not exists pro_private_estimate_publication_recipients(owner_id uuid not null references profiles(id) on delete cascade,estimate_id uuid not null,client_id text not null,recipient_id uuid not null,proof jsonb not null,at timestamptz not null default clock_timestamp(),primary key(owner_id,estimate_id),foreign key(owner_id,estimate_id) references pro_private_estimates(owner_id,id) on delete cascade);
create table if not exists pro_private_estimate_publication_events(publication_id uuid not null references pro_private_estimate_publications(id) on delete cascade,action_id uuid not null,action text not null,revision integer not null,actor_id uuid not null,note text not null default '' check(length(note)<=1000),at timestamptz not null default clock_timestamp(),primary key(publication_id,revision));
create table if not exists pro_private_estimate_publication_actions(actor_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,input_hash text not null check(input_hash~'^[a-f0-9]{64}$'),result jsonb not null,publication_id uuid not null references pro_private_estimate_publications(id) on delete cascade,at timestamptz not null default clock_timestamp(),primary key(actor_id,action_id),check(not(input?'code') and not coalesce((input->'recipient')?'code',false)));
create index if not exists pro_private_estimate_publication_owner_page on pro_private_estimate_publications(owner_id,created_at desc,id desc);
create index if not exists pro_private_estimate_publication_client_page on pro_private_estimate_publication_states(recipient_id,publication_id);
create or replace function pro_private_estimate_publication_json(p_id uuid,p_actor uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$ select jsonb_build_object('publicationId',v.id,'estimateId',case when v.owner_id=p_actor then v.estimate_id else null end,'version',v.version,'estimateRevision',v.estimate_revision,'content',v.content,'contentHash',v.content_hash,'revision',s.revision,'status',s.status,'recipientBound',s.recipient_id is not null,'createdAt',v.created_at) from pro_private_estimate_publications v join pro_private_estimate_publication_states s on s.publication_id=v.id where v.id=p_id $$;
create or replace function pro_private_estimate_publication_authorize(p_actor uuid,p_id uuid,p_write boolean default false) returns text language plpgsql volatile security invoker set search_path=public,pg_temp as $$declare v pro_private_estimate_publications;s pro_private_estimate_publication_states;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;select * into v from pro_private_estimate_publications where id=p_id;select * into s from pro_private_estimate_publication_states where publication_id=p_id;
 if v.id is null then raise exception 'Publication unavailable' using errcode='P0002';end if;
 if p_actor=v.owner_id then if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;return 'owner';end if;
 if s.recipient_id is distinct from p_actor or p_write and not coalesce(pro_private_work_tools_enabled(v.owner_id),false) then raise exception 'Forbidden' using errcode='42501';end if;return 'client';end $$;
create or replace function pro_private_estimate_publication_context(p_actor uuid,p_estimate uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare d pro_private_estimates;recipient uuid;accepted boolean;begin if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into d from pro_private_estimates where owner_id=p_actor and id=p_estimate;if not found then return null;end if;select recipient_id into recipient from pro_private_estimate_publication_recipients where owner_id=p_actor and estimate_id=p_estimate;select exists(select 1 from pro_private_estimate_publications v join pro_private_estimate_publication_states s on s.publication_id=v.id where v.owner_id=p_actor and v.estimate_id=p_estimate and s.status='accepted') into accepted;return jsonb_build_object('estimateId',d.id,'estimateRevision',d.revision,'recipientId',recipient,'accepted',accepted,'canPublish',not accepted and not d.archived);end $$;
create or replace function pro_private_estimate_publication_mutate(p_actor uuid,p_input jsonb,p_input_hash text,p_verified_email text default null) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare act text;aid uuid;pid uuid;eid uuid;own uuid;v pro_private_estimate_publications;s pro_private_estimate_publication_states;prior pro_private_estimate_publication_actions;d pro_private_estimates;inv pro_private_estimate_publication_invites;r pro_appointment_requests;w pro_work;binding pro_private_estimate_publication_recipients;side text;recipient uuid;content jsonb;doc jsonb;lines jsonb;answer jsonb;next_revision integer;num integer;note_text text:='';old_id uuid;keys text[];begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or not coalesce(p_input_hash~'^[a-f0-9]{64}$',false) then raise exception 'Invalid operation' using errcode='22023';end if;
 act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;if aid is null then raise exception 'Invalid action identity' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;
 if act='publish' then
 if keys is distinct from array['action','actionId','estimateId','estimateRevision','publicationId','recipient'] or jsonb_typeof(p_input->'recipient') is distinct from 'object' then raise exception 'Invalid publish fields' using errcode='22023';end if;eid:=(p_input->>'estimateId')::uuid;pid:=(p_input->>'publicationId')::uuid;own:=p_actor;
 elsif act='claim' then
 if keys is distinct from array['action','actionId','codeHash'] or not coalesce(p_input->>'codeHash'~'^[a-f0-9]{64}$',false) then raise exception 'Invalid claim' using errcode='22023';end if;select * into inv from pro_private_estimate_publication_invites where code_hash=p_input->>'codeHash';if not found or p_verified_email is null or lower(btrim(p_verified_email))<>inv.email then raise exception 'Code unavailable' using errcode='P0002';end if;pid:=inv.publication_id;
 else
 if act not in('accept','decline','withdraw','request_changes','respond_changes','rotate_code') or keys is distinct from (case when act='rotate_code' then array['action','actionId','codeHash','contentHash','publicationId','revision'] when act in('request_changes','respond_changes') then array['action','actionId','contentHash','note','publicationId','revision'] else array['action','actionId','contentHash','publicationId','revision'] end) then raise exception 'Invalid response fields' using errcode='22023';end if;pid:=(p_input->>'publicationId')::uuid;
 end if;
 if act<>'publish' then select * into v from pro_private_estimate_publications where id=pid;if not found then raise exception 'Publication unavailable' using errcode='P0002';end if;own:=v.owner_id;eid:=v.estimate_id;end if;
 -- Lock order: actor/action advisory -> estimate row -> invite (claim only) -> state.
 -- Linked publication additionally takes request SHARE, never a work row lock.
 -- Every writer shares estimate->state order, so response cannot deadlock republish.
 perform pg_advisory_xact_lock(hashtextextended('pro-private-estimate-publication-action:'||p_actor::text||':'||aid::text,0));
 select * into d from pro_private_estimates where owner_id=own and id=eid for update;if not found then raise exception 'Estimate unavailable' using errcode='42501';end if;
 if not coalesce(pro_private_work_tools_enabled(own),false) or not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if act='publish' then if p_actor<>own then raise exception 'Forbidden' using errcode='42501';end if;side:='owner';
 elsif act='claim' then
  select * into inv from pro_private_estimate_publication_invites where publication_id=pid for update;
  select * into s from pro_private_estimate_publication_states where publication_id=pid for update;
  if inv.code_hash is distinct from p_input->>'codeHash' or inv.email<>lower(btrim(p_verified_email)) or inv.claimed_by is not null and inv.claimed_by<>p_actor then raise exception 'Code unavailable' using errcode='P0002';end if;
  if inv.claimed_by=p_actor then side:='client';else if inv.expires_at<=clock_timestamp() or s.status<>'awaiting_claim' or p_actor=own then raise exception 'Code unavailable' using errcode='P0002';end if;side:='client';end if;
 else side:=pro_private_estimate_publication_authorize(p_actor,pid,true);select * into s from pro_private_estimate_publication_states where publication_id=pid for update;end if;
 -- Current rights are checked after every lock wait, before immutable receipt replay.
 if not coalesce(pro_private_work_tools_enabled(own),false) or not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if act not in('publish','claim') then side:=pro_private_estimate_publication_authorize(p_actor,pid,true);end if;
 select * into prior from pro_private_estimate_publication_actions where actor_id=p_actor and action_id=aid;if found then if prior.input is distinct from p_input or prior.input_hash<>p_input_hash then raise exception 'Action identity reused' using errcode='22023';end if;return prior.result;end if;
 if act<>'publish' and s.revision>=2147483647 then raise exception 'Publication revision exhausted' using errcode='40001';end if;
 if act='publish' then
  if d.archived or not coalesce(p_input->>'estimateRevision'~'^[0-9]+$',false) or d.revision<>(p_input->>'estimateRevision')::integer then raise exception 'Saved draft changed' using errcode='40001';end if;
  if exists(select 1 from pro_private_estimate_publications pv join pro_private_estimate_publication_states ps on ps.publication_id=pv.id where pv.owner_id=own and pv.estimate_id=eid and ps.status='accepted') then raise exception 'Accepted version is immutable' using errcode='40001';end if;
  if pid is null or exists(select 1 from pro_private_estimate_publications where id=pid) then raise exception 'Publication identity reused' using errcode='40001';end if;
  select * into binding from pro_private_estimate_publication_recipients where owner_id=own and estimate_id=eid;
  if binding.recipient_id is not null and binding.client_id<>d.client_id then raise exception 'Bound customer identity changed' using errcode='40001';end if;
  if p_input->'recipient'->>'kind'='linked' then
   select * into r from pro_appointment_requests where id=(p_input->'recipient'->>'requestId')::uuid and owner_id=own for share;
   -- No work row lock: pro_appointment_sync_work (appointment-reschedule-local.sql:77)
   -- forbids clientId/bookingClientId changes after taking this request's UPDATE lock.
   -- Keep request SHARE; a concurrent cancellation waiting for it serializes after publish.
   select * into w from pro_work where user_id=own and id=r.work_id;
   recipient:=(p_input->'recipient'->>'recipientId')::uuid;
   if r.id is null or recipient is null or r.client_user_id<>recipient or r.status not in('confirmed','completed') or w.id is null or w."clientId"<>d.client_id or not(w."bookingClientId" is not distinct from recipient::text or r.origin='project_invite' and w."bookingClientId" is null) or coalesce(w.cancelled,false) or d.source->>'kind'='work' and d.source->>'id'<>w.id then raise exception 'Recipient binding changed' using errcode='40001';end if;
  elsif p_input->'recipient'->>'kind'='existing' then recipient:=(p_input->'recipient'->>'recipientId')::uuid;if binding.recipient_id is distinct from recipient or recipient is null then raise exception 'Recipient changed' using errcode='40001';end if;
  elsif p_input->'recipient'->>'kind'='claim' then
   if binding.recipient_id is not null or not coalesce(p_input->'recipient'->>'codeHash'~'^[a-f0-9]{64}$',false) or not coalesce(p_input->'recipient'->>'email'~'^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$',false) or length(p_input->'recipient'->>'email')>254 or lower(btrim(p_input->'recipient'->>'email'))<>p_input->'recipient'->>'email' then raise exception 'Recipient changed' using errcode='40001';end if;
  else raise exception 'Invalid recipient' using errcode='22023';end if;
  if recipient is not null and(recipient=own or not exists(select 1 from profiles where id=recipient and not coalesce(is_disabled,false)) or binding.recipient_id is not null and binding.recipient_id<>recipient) then raise exception 'Recipient unavailable' using errcode='40001';end if;
  if recipient is not null and binding.recipient_id is null then insert into pro_private_estimate_publication_recipients values(own,eid,d.client_id,recipient,p_input->'recipient',clock_timestamp());end if;
  if exists(select 1 from pro_private_estimate_publications pv join pro_private_estimate_publication_states ps on ps.publication_id=pv.id where pv.owner_id=own and pv.estimate_id=eid and ps.status in('awaiting_claim','shared','changes_requested') and ps.revision>=2147483647) then raise exception 'Publication revision exhausted' using errcode='40001';end if;
  for old_id in select pv.id from pro_private_estimate_publications pv join pro_private_estimate_publication_states ps on ps.publication_id=pv.id where pv.owner_id=own and pv.estimate_id=eid and ps.status in('awaiting_claim','shared','changes_requested') order by pv.id for update of ps loop
   update pro_private_estimate_publication_states set status='superseded',revision=revision+1 where publication_id=old_id returning revision into next_revision;insert into pro_private_estimate_publication_events values(old_id,aid,'supersede',next_revision,p_actor,'',clock_timestamp());
  end loop;
  doc:=pro_private_estimate_json(d);select jsonb_agg(jsonb_build_object('id',value->'id','description',value->'description','unit',value->'unit','qtyMilli',value->'qtyMilli','unitPriceCents',value->'unitPriceCents','discountBps',value->'discountBps','taxBps',value->'taxBps')||jsonb_strip_nulls(jsonb_build_object('group',value->'group')) order by ord) into lines from jsonb_array_elements(doc->'lines')with ordinality e(value,ord);
  content:=jsonb_build_object('title',d.title,'currency',d.currency,'validUntil',d.valid_until,'notes',d.notes,'issuer',jsonb_build_object('issuerName',d.issuer->'issuerName','issuerIdType',d.issuer->'issuerIdType','issuerId',d.issuer->'issuerId','issuerEmail',d.issuer->'issuerEmail','issuerPhone',d.issuer->'issuerPhone','issuerAddress',d.issuer->'issuerAddress'),'customer',jsonb_build_object('name',d.client_snapshot->'name','tradeName',d.client_snapshot->'tradeName','identification',d.client_snapshot->'identification','address',d.client_snapshot->'address'),'lines',lines,'subtotalCents',d.subtotal_cents,'discountCents',d.discount_cents,'taxCents',d.tax_cents,'totalCents',d.total_cents);
  select coalesce(max(version),0) into num from pro_private_estimate_publications where owner_id=own and estimate_id=eid;
  if num>=2147483647 then raise exception 'Publication version exhausted' using errcode='40001';end if;num:=num+1;
  insert into pro_private_estimate_publications values(own,pid,eid,d.client_id,num,d.revision,content,encode(sha256(convert_to(content::text,'UTF8')),'hex'),greatest(clock_timestamp(),coalesce((select max(created_at)+interval '1 microsecond' from pro_private_estimate_publications where owner_id=own and estimate_id=eid),clock_timestamp())));insert into pro_private_estimate_publication_states values(pid,1,case when recipient is null then 'awaiting_claim' else 'shared' end,recipient);
  if recipient is null then insert into pro_private_estimate_publication_invites values(pid,p_input->'recipient'->>'codeHash',p_input->'recipient'->>'email',clock_timestamp()+interval '72 hours',null,null);end if;next_revision:=1;
 elsif act='claim' then
  if inv.claimed_by is not null then raise exception 'Claim already recorded' using errcode='40001';end if;
  select * into binding from pro_private_estimate_publication_recipients where owner_id=own and estimate_id=eid;if binding.recipient_id is not null and binding.recipient_id<>p_actor then raise exception 'Recipient changed' using errcode='40001';end if;
  insert into pro_private_estimate_publication_recipients values(own,eid,v.client_id,p_actor,jsonb_build_object('kind','verified_claim','publicationId',pid),clock_timestamp()) on conflict(owner_id,estimate_id) do nothing;
  update pro_private_estimate_publication_invites set claimed_by=p_actor,claimed_at=clock_timestamp() where publication_id=pid;update pro_private_estimate_publication_states set recipient_id=p_actor,status='shared',revision=revision+1 where publication_id=pid returning revision into next_revision;
 else
  if not coalesce(p_input->>'revision'~'^[0-9]+$',false) or s.revision<>(p_input->>'revision')::integer or v.content_hash is distinct from p_input->>'contentHash' then raise exception 'Published version changed' using errcode='40001';end if;
  if s.status not in('shared','changes_requested','awaiting_claim') then raise exception 'Publication already resolved' using errcode='40001';end if;
  if act='rotate_code' then if side<>'owner' or s.status<>'awaiting_claim' or s.recipient_id is not null or not coalesce(p_input->>'codeHash'~'^[a-f0-9]{64}$',false) then raise exception 'Code cannot be rotated' using errcode='40001';end if;
  elsif act='withdraw' then if side<>'owner' then raise exception 'Forbidden' using errcode='42501';end if;
  elsif act='respond_changes' then if side<>'owner' or s.status<>'changes_requested' then raise exception 'Forbidden' using errcode='42501';end if;
  else if side<>'client' or s.status not in('shared','changes_requested') then raise exception 'Forbidden' using errcode='42501';end if;if v.content->>'validUntil' is not null and(v.content->>'validUntil')::date<(clock_timestamp() at time zone 'America/Costa_Rica')::date then raise exception 'Publication expired' using errcode='40001';end if;end if;
  if act in('request_changes','respond_changes') then note_text:=btrim(p_input->>'note');if jsonb_typeof(p_input->'note') is distinct from 'string' or length(note_text) not between 1 and 1000 then raise exception 'Invalid change note' using errcode='22023';end if;end if;
  if act='rotate_code' then update pro_private_estimate_publication_invites set code_hash=p_input->>'codeHash',expires_at=clock_timestamp()+interval '72 hours' where publication_id=pid and claimed_by is null;if not found then raise exception 'Claim changed' using errcode='40001';end if;end if;
  update pro_private_estimate_publication_states set status=case act when 'accept' then 'accepted' when 'decline' then 'declined' when 'withdraw' then 'withdrawn' when 'request_changes' then 'changes_requested' when 'respond_changes' then 'changes_requested' when 'rotate_code' then 'awaiting_claim' else 'shared' end,revision=revision+1 where publication_id=pid returning revision into next_revision;
 end if;
 insert into pro_private_estimate_publication_events values(pid,aid,act,next_revision,p_actor,note_text,clock_timestamp());answer:=jsonb_build_object('action',act,'publication',pro_private_estimate_publication_json(pid,p_actor));
 if not coalesce(pro_private_work_tools_enabled(own),false) or not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 insert into pro_private_estimate_publication_actions values(p_actor,aid,p_input,p_input_hash,answer,pid,clock_timestamp());return answer;end $$;
create or replace function pro_private_estimate_publication_read(p_actor uuid,p_publication uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare side text;v pro_private_estimate_publications;s pro_private_estimate_publication_states;can_write boolean;email_text text;begin
 side:=pro_private_estimate_publication_authorize(p_actor,p_publication,false);select * into v from pro_private_estimate_publications where id=p_publication;select * into s from pro_private_estimate_publication_states where publication_id=p_publication;
 can_write:=coalesce(pro_private_work_tools_enabled(v.owner_id),false) and s.status in('shared','changes_requested') and(v.content->>'validUntil' is null or(v.content->>'validUntil')::date>=(clock_timestamp() at time zone 'America/Costa_Rica')::date);
 if side='owner' then select email into email_text from pro_private_estimate_publication_invites where publication_id=p_publication;end if;
 return jsonb_build_object('publication',pro_private_estimate_publication_json(p_publication,p_actor),'side',side,'canRespond',side='client' and can_write,'canWithdraw',side='owner' and s.status in('awaiting_claim','shared','changes_requested'),'canRespondChanges',side='owner' and s.status='changes_requested','recipient',case when side='owner' then jsonb_build_object('recipientId',s.recipient_id,'email',email_text) else null end);end $$;
create or replace function pro_private_estimate_publication_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_private_estimate_publication_actions;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;select * into r from pro_private_estimate_publication_actions where actor_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_private_estimate_publication_authorize(p_actor,r.publication_id,false);return jsonb_build_object('receipt',jsonb_build_object('inputHash',r.input_hash,'result',r.result));end $$;
create or replace function pro_private_estimate_publication_list(p_actor uuid,p_side text default 'owner',p_after uuid default null,p_estimate uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare items jsonb;cursor_time timestamptz;next_id uuid;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) or p_side='owner' and not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_side not in('owner','client') or p_side='client' and p_estimate is not null then raise exception 'Invalid publication query' using errcode='22023';end if;
 if p_after is not null then select v.created_at into cursor_time from pro_private_estimate_publications v join pro_private_estimate_publication_states s on s.publication_id=v.id where v.id=p_after and(case when p_side='owner' then v.owner_id=p_actor else s.recipient_id=p_actor end) and(p_estimate is null or v.estimate_id=p_estimate);if not found then raise exception 'Cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg((pro_private_estimate_publication_json(v.id,p_actor)-'content')||jsonb_build_object('title',v.content->'title','currency',v.content->'currency','totalCents',v.content->'totalCents') order by v.created_at desc,v.id desc),'[]'::jsonb) into items from(select v.* from pro_private_estimate_publications v join pro_private_estimate_publication_states s on s.publication_id=v.id where(case when p_side='owner' then v.owner_id=p_actor else s.recipient_id=p_actor end) and(p_estimate is null or v.estimate_id=p_estimate) and(p_after is null or(v.created_at,v.id)<(cursor_time,p_after))order by v.created_at desc,v.id desc limit 21)v;
 if jsonb_array_length(items)>20 then next_id:=(items->19->>'publicationId')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',next_id);end $$;
create or replace function pro_private_estimate_publication_history(p_actor uuid,p_publication uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare items jsonb;cursor_revision integer;own uuid;next_id uuid;begin
 perform pro_private_estimate_publication_authorize(p_actor,p_publication,false);select owner_id into own from pro_private_estimate_publications where id=p_publication;
 if p_after is not null then select revision into cursor_revision from pro_private_estimate_publication_events where publication_id=p_publication and action_id=p_after;if not found then raise exception 'History cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('actionId',e.action_id,'action',e.action,'revision',e.revision,'actorSide',case when e.actor_id=own then 'owner' else 'client' end,'note',e.note,'at',e.at) order by e.revision desc),'[]'::jsonb) into items from(select * from pro_private_estimate_publication_events where publication_id=p_publication and(p_after is null or revision<cursor_revision)order by revision desc limit 21)e;
 if jsonb_array_length(items)>20 then next_id:=(items->19->>'actionId')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',next_id);end $$;
-- Round 7A (2026-11-13): a customer ACCOUNT linked to the job by invitation (origin project_invite,
-- no booking) is a valid «linked» recipient too, so the owner shares to it directly, without a code.
create or replace function pro_private_estimate_publication_bindings(p_actor uuid,p_estimate uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare d pro_private_estimates;items jsonb;next_id uuid;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into d from pro_private_estimates where owner_id=p_actor and id=p_estimate;if not found then return null;end if;
 if p_after is not null and not exists(select 1 from pro_appointment_requests r join pro_work w on w.user_id=r.owner_id and w.id=r.work_id join profiles p on p.id=r.client_user_id and not coalesce(p.is_disabled,false) where r.id=p_after and r.owner_id=p_actor and r.status in('confirmed','completed') and w."clientId"=d.client_id and (w."bookingClientId"=r.client_user_id::text or r.origin='project_invite' and w."bookingClientId" is null) and not coalesce(w.cancelled,false) and(d.source->>'kind' is distinct from 'work' or d.source->>'id'=w.id)) then raise exception 'Binding cursor changed' using errcode='40001';end if;
 select coalesce(jsonb_agg(jsonb_build_object('requestId',r.id,'recipientId',r.client_user_id,'name',r.client_name)order by r.id),'[]'::jsonb) into items from(select r.* from pro_appointment_requests r join pro_work w on w.user_id=r.owner_id and w.id=r.work_id join profiles p on p.id=r.client_user_id and not coalesce(p.is_disabled,false) where r.owner_id=p_actor and r.status in('confirmed','completed') and w."clientId"=d.client_id and (w."bookingClientId"=r.client_user_id::text or r.origin='project_invite' and w."bookingClientId" is null) and not coalesce(w.cancelled,false) and(d.source->>'kind' is distinct from 'work' or d.source->>'id'=w.id) and(p_after is null or r.id>p_after)order by r.id limit 21)r;
 if jsonb_array_length(items)>20 then next_id:=(items->19->>'requestId')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',next_id);end $$;
create or replace function pro_private_estimate_publication_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if tg_op='DELETE' then
  if tg_table_name in('pro_private_estimate_publications','pro_private_estimate_publication_recipients') then
   if not exists(select 1 from profiles where id=old.owner_id) then return old;end if;
  elsif tg_table_name='pro_private_estimate_publication_events' then
   if not exists(select 1 from pro_private_estimate_publications where id=old.publication_id) then return old;end if;
  elsif tg_table_name='pro_private_estimate_publication_actions' then
   if not exists(select 1 from profiles where id=old.actor_id) or not exists(select 1 from pro_private_estimate_publications where id=old.publication_id) then return old;end if;
  end if;
 end if;
 raise exception 'Immutable publication record' using errcode='23514';end $$;
drop trigger if exists pro_private_estimate_publication_immutable on pro_private_estimate_publications;create trigger pro_private_estimate_publication_immutable before update or delete on pro_private_estimate_publications for each row execute function pro_private_estimate_publication_immutable();
drop trigger if exists pro_private_estimate_publication_recipient_immutable on pro_private_estimate_publication_recipients;create trigger pro_private_estimate_publication_recipient_immutable before update or delete on pro_private_estimate_publication_recipients for each row execute function pro_private_estimate_publication_immutable();
drop trigger if exists pro_private_estimate_publication_event_immutable on pro_private_estimate_publication_events;create trigger pro_private_estimate_publication_event_immutable before update or delete on pro_private_estimate_publication_events for each row execute function pro_private_estimate_publication_immutable();
drop trigger if exists pro_private_estimate_publication_action_immutable on pro_private_estimate_publication_actions;create trigger pro_private_estimate_publication_action_immutable before update or delete on pro_private_estimate_publication_actions for each row execute function pro_private_estimate_publication_immutable();
do $$declare t text;f record;begin foreach t in array array['pro_private_estimate_publications','pro_private_estimate_publication_states','pro_private_estimate_publication_invites','pro_private_estimate_publication_recipients','pro_private_estimate_publication_events','pro_private_estimate_publication_actions'] loop execute format('alter table %I enable row level security',t);execute format('revoke all on %I from public,anon,authenticated',t);execute format('grant all on %I to service_role',t);end loop;for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro_private_estimate_publication_%' loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst, 'reload schema';

-- ===== private-estimate-work-local.sql =====
-- LOCAL Pro only. Accepted estimate -> original commercial reference, NOT a balance/debt.
-- No booking, financial posting, inventory, public quote or notification writes.
begin;
-- Exact immutable revision lookup for publication lineage; no history backfill.
create index if not exists pro_private_estimate_history_revision_lookup on public.pro_private_estimate_history(owner_id,estimate_id,((after_estimate->>'revision')::integer));
create table if not exists pro_private_estimate_work_agreements(
 owner_id uuid not null references profiles(id) on delete cascade,work_id text not null,publication_id uuid not null unique references pro_private_estimate_publications(id) on delete cascade,
 estimate_id uuid not null,version integer not null,estimate_revision integer not null,client_id text not null,title text not null,currency text not null check(currency in('CRC','USD')),total_cents bigint not null check(total_cents between 0 and 9000000000000),content_hash text not null,
 accepted_action_id uuid not null,accepted_actor_id uuid not null,accepted_at timestamptz not null,source_snapshot jsonb not null,work_snapshot jsonb not null,created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,work_id),foreign key(owner_id,work_id) references pro_work(user_id,id) on delete cascade);
create table if not exists pro_private_estimate_work_actions(actor_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,publication_id uuid not null references pro_private_estimate_publications(id) on delete cascade,at timestamptz not null default clock_timestamp(),primary key(actor_id,action_id));
create or replace function pro_private_estimate_work_json(p_work pro_work) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('id',p_work.id,'client',p_work.client,'service',p_work.service,'stage',p_work.stage,'start',p_work.start,'end',p_work."end",'clientId',p_work."clientId",'cancelled',p_work.cancelled,'bookingClientId',p_work."bookingClientId",'quoteId',p_work."quoteId",'externalQuoteId',p_work."externalQuoteId")$$;
create or replace function pro_private_estimate_work_agreement_json(p_agreement pro_private_estimate_work_agreements) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('publicationId',p_agreement.publication_id,'estimateId',p_agreement.estimate_id,'version',p_agreement.version,'estimateRevision',p_agreement.estimate_revision,'workId',p_agreement.work_id,'clientId',p_agreement.client_id,'title',p_agreement.title,'currency',p_agreement.currency,'totalCents',p_agreement.total_cents,'contentHash',p_agreement.content_hash,'acceptedActionId',p_agreement.accepted_action_id,'acceptedActorId',p_agreement.accepted_actor_id,'acceptedAt',p_agreement.accepted_at,'source',p_agreement.source_snapshot->'source','createdAt',p_agreement.created_at)$$;
-- Launch fix (2026-11-17, old bug 4): the projection keeps each line's section (group), exactly as the
-- publication writer does; without it every grouped quote failed «Historical publication content mismatch»,
-- so its acceptance never reached the job (agreed amount «Sin definir»).
create or replace function pro_private_estimate_work_source(p_actor uuid,p_publication uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare v pro_private_estimate_publications;s pro_private_estimate_publication_states;e pro_private_estimate_publication_events;r pro_private_estimate_publication_actions;hist jsonb;snapshot jsonb;projected jsonb;lines jsonb;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into v from pro_private_estimate_publications where id=p_publication and owner_id=p_actor;if not found then raise exception 'Publication unavailable' using errcode='42501';end if;select * into s from pro_private_estimate_publication_states where publication_id=v.id;
 if s.status is distinct from 'accepted' then raise exception 'Actual client acceptance required' using errcode='40001';end if;
 select * into e from pro_private_estimate_publication_events where publication_id=v.id and action='accept' and revision=s.revision;
 if not found or e.actor_id is distinct from s.recipient_id or e.actor_id=p_actor then raise exception 'Acceptance evidence unavailable' using errcode='40001';end if;
 select * into r from pro_private_estimate_publication_actions where actor_id=e.actor_id and action_id=e.action_id;
 if found then
  if r.publication_id<>v.id or r.input->>'action' is distinct from 'accept' or r.input->>'publicationId' is distinct from v.id::text or r.input->>'contentHash' is distinct from v.content_hash or r.input->'revision' is distinct from to_jsonb(s.revision-1) or r.result->>'action' is distinct from 'accept' or r.result->'publication'->>'publicationId' is distinct from v.id::text or r.result->'publication'->'version' is distinct from to_jsonb(v.version) or r.result->'publication'->'revision' is distinct from to_jsonb(s.revision) or r.result->'publication'->>'contentHash' is distinct from v.content_hash or r.result->'publication'->'content' is distinct from v.content or r.result->'publication'->>'status' is distinct from 'accepted' then raise exception 'Acceptance receipt mismatch' using errcode='40001';end if;
 elsif exists(select 1 from profiles where id=e.actor_id) then raise exception 'Acceptance receipt unavailable' using errcode='40001';end if;
 select jsonb_agg(h.after_estimate) into hist from pro_private_estimate_history h where h.owner_id=p_actor and h.estimate_id=v.estimate_id and(h.after_estimate->>'revision')::integer=v.estimate_revision;
 if jsonb_array_length(coalesce(hist,'[]'::jsonb))<>1 then raise exception 'Historical source unavailable' using errcode='40001';end if;snapshot:=hist->0;
 if snapshot->>'id'<>v.estimate_id::text or snapshot->>'ownerId'<>p_actor::text or snapshot->>'clientId'<>v.client_id then raise exception 'Historical source identity mismatch' using errcode='40001';end if;
 select jsonb_agg(jsonb_build_object('id',value->'id','description',value->'description','unit',value->'unit','qtyMilli',value->'qtyMilli','unitPriceCents',value->'unitPriceCents','discountBps',value->'discountBps','taxBps',value->'taxBps')||jsonb_strip_nulls(jsonb_build_object('group',value->'group'))order by ord)into lines from jsonb_array_elements(snapshot->'lines')with ordinality e(value,ord);
 projected:=jsonb_build_object('title',snapshot->'title','currency',snapshot->'currency','validUntil',snapshot->'validUntil','notes',snapshot->'notes','issuer',jsonb_build_object('issuerName',snapshot->'issuer'->'issuerName','issuerIdType',snapshot->'issuer'->'issuerIdType','issuerId',snapshot->'issuer'->'issuerId','issuerEmail',snapshot->'issuer'->'issuerEmail','issuerPhone',snapshot->'issuer'->'issuerPhone','issuerAddress',snapshot->'issuer'->'issuerAddress'),'customer',jsonb_build_object('name',snapshot->'client'->'name','tradeName',snapshot->'client'->'tradeName','identification',snapshot->'client'->'identification','address',snapshot->'client'->'address'),'lines',lines,'subtotalCents',snapshot->'subtotalCents','discountCents',snapshot->'discountCents','taxCents',snapshot->'taxCents','totalCents',snapshot->'totalCents');
 if projected is distinct from v.content then raise exception 'Historical publication content mismatch' using errcode='40001';end if;
 return jsonb_build_object('publicationId',v.id,'estimateId',v.estimate_id,'estimateRevision',v.estimate_revision,'version',v.version,'publicationRevision',s.revision,'clientId',v.client_id,'title',v.content->'title','currency',v.content->'currency','totalCents',v.content->'totalCents','contentHash',v.content_hash,'source',snapshot->'source','sourceSnapshot',snapshot,'accepted',jsonb_build_object('actionId',e.action_id,'actorId',e.actor_id,'at',e.at));end $$;
create or replace function pro_private_estimate_work_reason(p_actor uuid,p_work text,p_client text,p_recipient uuid,p_publication uuid)returns text language plpgsql stable security invoker set search_path=public,pg_temp as $$declare w pro_work;begin
 select * into w from pro_work where user_id=p_actor and id=p_work;if not found then return 'source_unavailable';end if;
 if w."clientId" is distinct from p_client or w."bookingClientId" is not null and w."bookingClientId"<>p_recipient::text then return 'work_customer_changed';end if;if w.cancelled then return 'work_cancelled';end if;
 if exists(select 1 from pro_private_estimate_work_agreements where owner_id=p_actor and work_id=p_work and publication_id<>p_publication)then return 'work_already_linked';end if;
 if coalesce(w."quoteId",'')<>'' or coalesce(w."externalQuoteId",'')<>'' or exists(select 1 from pro_client_entries where user_id=p_actor and work_id=p_work and kind in('agreement','payment','payment_void'))then return 'legacy_finance';end if;return null;end $$;
create or replace function pro_private_estimate_work_mapping(p_actor uuid,p_publication uuid default null,p_work text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare a pro_private_estimate_work_agreements;w pro_work;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;if(p_publication is null)=(p_work is null)then raise exception 'Choose exactly one mapping scope' using errcode='22023';end if;
 select * into a from pro_private_estimate_work_agreements where owner_id=p_actor and(case when p_publication is not null then publication_id=p_publication else work_id=p_work end);
 if not found then return jsonb_build_object('agreement',null,'work',null);end if;
 select * into w from pro_work where user_id=p_actor and id=a.work_id;
 if not found or w."clientId"<>a.client_id or w."bookingClientId" is distinct from a.work_snapshot->>'bookingClientId' or coalesce(w."quoteId",'')<>coalesce(a.work_snapshot->>'quoteId','') or coalesce(w."externalQuoteId",'')<>coalesce(a.work_snapshot->>'externalQuoteId','') then raise exception 'Agreement work identity changed' using errcode='42501';end if;
 return jsonb_build_object('agreement',pro_private_estimate_work_agreement_json(a),'work',pro_private_estimate_work_json(w));end $$;
create or replace function pro_private_estimate_work_context(p_actor uuid,p_publication uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare evidence jsonb;c pro_clients;l pro_lead_center_records;m pro_manual_lead_works;w pro_work;mapping jsonb;required jsonb;manual jsonb;reason text;src jsonb;begin
 evidence:=pro_private_estimate_work_source(p_actor,p_publication);src:=evidence->'source';mapping:=pro_private_estimate_work_mapping(p_actor,p_publication,null);
 select * into c from pro_clients where user_id=p_actor and id=evidence->>'clientId';if not found then raise exception 'Private customer unavailable' using errcode='42501';end if;
 if c.archived then reason:='client_archived';end if;
 if src->>'kind'='work' then
  select * into w from pro_work where user_id=p_actor and id=src->>'id';if not found then reason:=coalesce(reason,'source_unavailable');else required:=jsonb_build_object('work',pro_private_estimate_work_json(w),'fingerprint',md5(to_jsonb(w)::text),'reason','source_work');end if;
 elsif src->>'kind'='manual' then
  select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=(src->>'id')::uuid;
  if not found then reason:=coalesce(reason,'source_unavailable');else
   select * into m from pro_manual_lead_works where owner_id=p_actor and lead_id=l.id;
   if found then select * into w from pro_work where user_id=p_actor and id=m.work_id_text;if not found then reason:=coalesce(reason,'source_unavailable');else required:=jsonb_build_object('work',pro_private_estimate_work_json(w),'fingerprint',md5(to_jsonb(w)::text),'reason','converted_manual');end if;
   else if l.archived then reason:=coalesce(reason,'source_archived');elsif l.client_id<>c.id then reason:=coalesce(reason,'source_customer_changed');end if;end if;
   manual:=jsonb_build_object('id',l.id,'currentRevision',l.revision,'canConvert',required is null and reason is null);
  end if;
 end if;
 if required is not null then reason:=coalesce(reason,pro_private_estimate_work_reason(p_actor,w.id,c.id,(evidence->'accepted'->>'actorId')::uuid,p_publication));end if;
 return jsonb_build_object('publicationId',p_publication,'contentHash',evidence->'contentHash','publicationRevision',evidence->'publicationRevision','version',evidence->'version','currency',evidence->'currency','totalCents',evidence->'totalCents','accepted',evidence->'accepted','source',src,'client',jsonb_build_object('id',c.id,'name',c.name,'archived',c.archived),'mapping',mapping->'agreement','requiredWork',required,'manual',manual,'canCreate',mapping->'agreement'='null'::jsonb and reason is null,'reason',case when mapping->'agreement'<>'null'::jsonb then null else reason end);end $$;
create or replace function pro_private_estimate_work_candidates(p_actor uuid,p_publication uuid,p_query text default '',p_after text default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare evidence jsonb;ctx jsonb;items jsonb;next_id text;begin
 if p_query is null or length(p_query)>100 or p_after is not null and length(p_after)not between 1 and 160 then raise exception 'Invalid candidate query' using errcode='22023';end if;evidence:=pro_private_estimate_work_source(p_actor,p_publication);ctx:=pro_private_estimate_work_context(p_actor,p_publication);
 if ctx->'requiredWork'<>'null'::jsonb or ctx->'source'->>'kind'='manual' or not(ctx->>'canCreate')::boolean then return jsonb_build_object('items','[]'::jsonb,'nextCursor',null);end if;
 if p_after is not null and not exists(select 1 from pro_work w where w.user_id=p_actor and w.id=p_after and position(lower(p_query)in lower(w.service||' '||w.client))>0 and pro_private_estimate_work_reason(p_actor,w.id,evidence->>'clientId',(evidence->'accepted'->>'actorId')::uuid,p_publication)is null)then raise exception 'Candidate cursor changed' using errcode='40001';end if;
 select coalesce(jsonb_agg(jsonb_build_object('work',pro_private_estimate_work_json(w),'fingerprint',md5(to_jsonb(w)::text))order by w.id),'[]'::jsonb)into items from(select * from pro_work w where w.user_id=p_actor and(p_after is null or w.id>p_after)and position(lower(p_query)in lower(w.service||' '||w.client))>0 and pro_private_estimate_work_reason(p_actor,w.id,evidence->>'clientId',(evidence->'accepted'->>'actorId')::uuid,p_publication)is null order by w.id limit 21)w;
 if jsonb_array_length(items)>20 then next_id:=items->19->'work'->>'id';items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',next_id);end $$;
create or replace function pro_private_estimate_work_action_read(p_actor uuid,p_action uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_private_estimate_work_actions;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden' using errcode='42501';end if;select * into r from pro_private_estimate_work_actions where actor_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_private_estimate_work_mapping(p_actor,r.publication_id,null);return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function pro_private_estimate_work_continue(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;pid uuid;wid text;child uuid;lead_rev integer;keys text[];r pro_private_estimate_work_actions;evidence jsonb;ctx jsonb;src jsonb;c pro_clients;l pro_lead_center_records;m pro_manual_lead_works;w pro_work;core_rev integer;row_json jsonb;answer jsonb;a pro_private_estimate_work_agreements;reason text;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)is distinct from'object' or(select array_agg(key order by key)from jsonb_object_keys(p_input)key)is distinct from array['action','actionId','contentHash','publicationId','publicationRevision','target'] or p_input->>'action'is distinct from'continue' then raise exception 'Invalid continuation' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;pid:=(p_input->>'publicationId')::uuid;wid:=p_input->'target'->>'workId';if aid is null or pid is null or length(wid)not between 1 and 160 or not coalesce(p_input->>'contentHash'~'^[a-f0-9]{64}$',false)or not coalesce(p_input->>'publicationRevision'~'^[0-9]+$',false) then raise exception 'Invalid continuation identity' using errcode='22023';end if;
 select array_agg(key order by key)into keys from jsonb_object_keys(p_input->'target')key;
 if p_input->'target'->>'kind'='existing' then if keys is distinct from array['fingerprint','kind','workId'] or not coalesce(p_input->'target'->>'fingerprint'~'^[a-f0-9]{32}$',false)then raise exception 'Invalid existing target' using errcode='22023';end if;
 elsif p_input->'target'->>'kind'='new' then if keys is distinct from array['conversionActionId','kind','leadRevision','workId']then raise exception 'Invalid new target' using errcode='22023';end if;perform wid::uuid;child:=(p_input->'target'->>'conversionActionId')::uuid;lead_rev:=(p_input->'target'->>'leadRevision')::integer;if(child is null)<>(lead_rev is null)or child=aid then raise exception 'Invalid child identity' using errcode='22023';end if;
 else raise exception 'Invalid target kind' using errcode='22023';end if;
 -- Global owner mutex is reentrant with client/core/conversion writers. Child
 -- conversion advisory precedes catalogue; no old writer locks this new ledger.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-private-estimate-work-action:'||p_actor::text||':'||aid::text,0));
 if child is not null then perform pg_advisory_xact_lock(hashtextextended('pro-manual-lead-work-action:'||p_actor::text||':'||child::text,0));end if;
 if not coalesce(pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_private_estimate_work_actions where actor_id=p_actor and action_id=aid;if found then perform pro_private_estimate_work_mapping(p_actor,r.publication_id,null);if r.input is distinct from p_input then raise exception 'Continuation identity reused'using errcode='22023';end if;return r.result;end if;
 if exists(select 1 from pro_private_estimate_work_agreements where publication_id=pid) then raise exception 'Publication already linked'using errcode='40001';end if;
 evidence:=pro_private_estimate_work_source(p_actor,pid);src:=evidence->'source';
 if src->>'kind'='manual' then perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));end if;
 perform 1 from pro_private_estimates where owner_id=p_actor and id=(evidence->>'estimateId')::uuid for update;perform 1 from pro_private_estimate_publication_states where publication_id=pid for update;
 evidence:=pro_private_estimate_work_source(p_actor,pid);if evidence->>'contentHash'<>p_input->>'contentHash' or(evidence->>'publicationRevision')::integer<>(p_input->>'publicationRevision')::integer then raise exception 'Accepted publication changed'using errcode='40001';end if;
 if src->>'kind'='manual' then perform 1 from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=(src->>'id')::uuid for update;end if;
 select * into c from pro_clients where user_id=p_actor and id=evidence->>'clientId' for update;if not found or c.archived then raise exception 'Restore the accepted customer first'using errcode='40001';end if;
 ctx:=pro_private_estimate_work_context(p_actor,pid);if not(ctx->>'canCreate')::boolean then raise exception 'Work continuation unavailable'using errcode='40001';end if;
 if ctx->'requiredWork'<>'null'::jsonb then if p_input->'target'->>'kind'<>'existing' or wid<>ctx->'requiredWork'->'work'->>'id' then raise exception 'Historical source work must be reused'using errcode='40001';end if;end if;
 if p_input->'target'->>'kind'='existing' then
  if src->>'kind'='manual' and ctx->'requiredWork'='null'::jsonb then raise exception 'Unconverted opportunity requires conversion'using errcode='40001';end if;
  -- NOWAIT avoids inverse old booking trigger order (work row -> owner mutex).
  begin select * into w from pro_work where user_id=p_actor and id=wid for update nowait;exception when lock_not_available then raise exception 'Work is being changed'using errcode='40001';end;
  if not found or md5(to_jsonb(w)::text)<>p_input->'target'->>'fingerprint'then raise exception 'Selected work changed'using errcode='40001';end if;
 else
  if ctx->'requiredWork'<>'null'::jsonb or exists(select 1 from pro_work where user_id=p_actor and id=wid)then raise exception 'New work identity unavailable'using errcode='40001';end if;
  if src->>'kind'='manual' then
   if child is null or lead_rev is null or lead_rev<1 or exists(select 1 from pro_manual_lead_works where owner_id=p_actor and action_id=child)then raise exception 'Conversion child identity unavailable'using errcode='40001';end if;
   select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=(src->>'id')::uuid;if l.client_id<>c.id or l.archived or l.revision<>lead_rev then raise exception 'Opportunity customer or revision changed'using errcode='40001';end if;
   perform pro_lead_commercial_work_convert(p_actor,jsonb_build_object('action','convert','actionId',child,'leadId',l.id,'leadRevision',lead_rev,'workId',wid));
   select * into w from pro_work where user_id=p_actor and id=wid;
  elsif src='null'::jsonb or src is null then
   if child is not null or lead_rev is not null then raise exception 'Direct work does not have a conversion child'using errcode='22023';end if;
   select revision into core_rev from pro_workspace_core where user_id=p_actor for update;
   row_json:=jsonb_build_object('id',wid,'client',c.name,'service',evidence->>'title','stage','new','start','','end','','clientId',c.id,'cancelled',false);perform pro_patch_core(p_actor,'work',row_json,coalesce(core_rev,0));select * into w from pro_work where user_id=p_actor and id=wid;
  else raise exception 'Historical source work must be reused'using errcode='40001';end if;
  if w.service<>evidence->>'title' then select revision into core_rev from pro_workspace_core where user_id=p_actor for update;row_json:=jsonb_strip_nulls(pro_private_estimate_work_json(w))||jsonb_build_object('service',evidence->>'title');perform pro_patch_core(p_actor,'work',row_json,core_rev);select * into w from pro_work where user_id=p_actor and id=wid;end if;
 end if;
 reason:=pro_private_estimate_work_reason(p_actor,wid,c.id,(evidence->'accepted'->>'actorId')::uuid,pid);if reason is not null then raise exception 'Existing finance or work identity conflicts with accepted estimate'using errcode='40001';end if;
 if not coalesce(pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden'using errcode='42501';end if;
 insert into pro_private_estimate_work_agreements(owner_id,work_id,publication_id,estimate_id,version,estimate_revision,client_id,title,currency,total_cents,content_hash,accepted_action_id,accepted_actor_id,accepted_at,source_snapshot,work_snapshot)values(p_actor,w.id,pid,(evidence->>'estimateId')::uuid,(evidence->>'version')::integer,(evidence->>'estimateRevision')::integer,c.id,evidence->>'title',evidence->>'currency',(evidence->>'totalCents')::bigint,evidence->>'contentHash',(evidence->'accepted'->>'actionId')::uuid,(evidence->'accepted'->>'actorId')::uuid,(evidence->'accepted'->>'at')::timestamptz,evidence->'sourceSnapshot',pro_private_estimate_work_json(w))returning * into a;
 answer:=jsonb_build_object('action','continue','agreement',pro_private_estimate_work_agreement_json(a),'work',pro_private_estimate_work_json(w));insert into pro_private_estimate_work_actions values(p_actor,aid,p_input,answer,pid,clock_timestamp());if not coalesce(pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden'using errcode='42501';end if;return answer;end $$;
create or replace function pro_private_estimate_work_guard()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if exists(select 1 from pro_private_estimate_work_agreements where owner_id=old.user_id and work_id=old.id)then
  if tg_op='DELETE' then if exists(select 1 from profiles where id=old.user_id)then raise exception 'Accepted commercial work cannot be deleted'using errcode='23514';end if;return old;end if;
  if new.user_id is distinct from old.user_id or new.id is distinct from old.id or new."clientId"is distinct from old."clientId"or new."bookingClientId"is distinct from old."bookingClientId"or coalesce(new."quoteId",'')<>coalesce(old."quoteId",'')or coalesce(new."externalQuoteId",'')<>coalesce(old."externalQuoteId",'')then raise exception 'Accepted commercial work identity is immutable'using errcode='23514';end if;
 end if;return case when tg_op='DELETE'then old else new end;end $$;
create or replace function pro_private_estimate_work_immutable()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if tg_op='DELETE' then if tg_table_name='pro_private_estimate_work_agreements' then if not exists(select 1 from profiles where id=old.owner_id)then return old;end if;elsif tg_table_name='pro_private_estimate_work_actions'then if not exists(select 1 from profiles where id=old.actor_id)then return old;end if;end if;end if;raise exception 'Immutable accepted estimate work history'using errcode='23514';end $$;
drop trigger if exists pro_private_estimate_work_guard on pro_work;
create trigger pro_private_estimate_work_guard before update or delete on pro_work for each row execute function pro_private_estimate_work_guard();
drop trigger if exists pro_private_estimate_work_agreement_immutable on pro_private_estimate_work_agreements;
create trigger pro_private_estimate_work_agreement_immutable before update or delete on pro_private_estimate_work_agreements for each row execute function pro_private_estimate_work_immutable();
drop trigger if exists pro_private_estimate_work_action_immutable on pro_private_estimate_work_actions;
create trigger pro_private_estimate_work_action_immutable before update or delete on pro_private_estimate_work_actions for each row execute function pro_private_estimate_work_immutable();
do $$declare t text;f record;begin foreach t in array array['pro_private_estimate_work_agreements','pro_private_estimate_work_actions']loop execute format('alter table %I enable row level security',t);execute format('revoke all on %I from public,anon,authenticated',t);execute format('grant all on %I to service_role',t);end loop;for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname like'pro_private_estimate_work_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst, 'reload schema';

-- ===== private-estimate-commercial-sales-local.sql =====
-- LOCAL Pro only. Commercial sales projection; no document/state/ledger writes.
-- Single allowlisted replacement, same signature/cursor and untouched legacy arms.
begin;
create or replace function pro_private_estimate_sales_page(p_actor uuid,p_status text default 'all',p_query text default '',p_client text default null,p_after jsonb default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;cursor jsonb;anchor_valid boolean;
begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_status not in('all','draft','sent','accepted','declined','withdrawn','archived') or length(p_query)>100 or p_after is not null and(jsonb_typeof(p_after)<>'object' or(select array_agg(key order by key) from jsonb_object_keys(p_after)key) is distinct from array['at','key'] or jsonb_typeof(p_after->'at')<>'string' or jsonb_typeof(p_after->'key')<>'string') then raise exception 'Invalid sales query' using errcode='22023';end if;
 -- Choose only immutable identity/version before joining its lightweight content
 -- header. No per-document RPC, line aggregation or serialized contact/document JSON.
 with latest as(
  select distinct on(v.estimate_id)v.estimate_id,v.id
  from pro_private_estimate_publications v where v.owner_id=p_actor
  order by v.estimate_id,v.version desc
 ),rows as(
  select 'private_estimate' kind,d.id::text id,'private_estimate:'||d.id::text key,
   case when p_query='' then null::text when v.id is null then d.title else v.content->>'title' end title,
   case when p_query='' then null::text when v.id is null then d.client_snapshot->>'name' else v.content->'customer'->>'name' end client,
   case when v.id is null then d.client_id else v.client_id end client_id,
   case when d.archived then 'archived' when v.id is null then 'draft'
    when s.status in('awaiting_claim','shared','changes_requested') then 'sent'
    when s.status in('withdrawn','superseded') then 'withdrawn' else s.status end status,
   null::text currency,null::numeric total_cents,
   to_char(coalesce(v.created_at,d.created_at)at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') at,
   case when v.id is null then null::jsonb else jsonb_build_object('publicationId',v.id,'version',v.version,'estimateRevision',v.estimate_revision,'revision',s.revision,'status',s.status,'contentHash',v.content_hash,'createdAt',v.created_at)end publication,
   jsonb_build_object('revision',d.revision,'status',case when d.archived then 'archived' else 'draft' end)draft,d.id private_estimate_id,v.id private_publication_id
  from pro_private_estimates d left join latest chosen on chosen.estimate_id=d.id
  left join pro_private_estimate_publications v on v.id=chosen.id and v.owner_id=d.owner_id
  left join pro_private_estimate_publication_states s on s.publication_id=v.id
  where d.owner_id=p_actor and(not d.archived or p_status='archived')
  union all
  select 'standard',q.id::text,'standard:'||q.id::text,coalesce(q.title,''),coalesce(q.client_name,''),l."clientId",q.status,'CRC',q.total::numeric*100,to_char(q.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),null::jsonb,null::jsonb,null::uuid,null::uuid
  from quotes q left join pro_quote_links l on l.user_id=p_actor and l."quoteId"=q.id::text where q.deleted_at is null and(q.client_id=p_actor or exists(select 1 from professionals p where p.id=q.professional_id and p.profile_id=p_actor))
  union all
  select 'legacy',q.id,'legacy:'||q.id,q.title,coalesce(c.name,''),q."clientId",q.status,'CRC',(select coalesce(sum(net+floor(net*l.tax::double precision/100+0.5)),0) from pro_legacy_quote_lines l cross join lateral(select floor(l.quantity::double precision*l.price::double precision*100+0.5)net)n where l.user_id=q.user_id and l.quote_id=q.id),'',null::jsonb,null::jsonb,null::uuid,null::uuid
  from pro_legacy_quotes q left join pro_clients c on c.user_id=q.user_id and c.id=q."clientId" where q.user_id=p_actor
 ),filtered as(
  select * from rows where(p_status='all' or status=p_status)and(p_client is null or client_id=p_client)and(p_query=''or position(lower(p_query)in lower(title||' '||client))>0)
 ),page as(
  select * from filtered where p_after is null or at<p_after->>'at' or at=p_after->>'at'and key>p_after->>'key'order by at desc,key asc limit 21
 )
 -- Resolve private display headers only for the selected twenty-plus-one rows.
 select coalesce(jsonb_agg(jsonb_build_object('kind',p.kind,'id',p.id,'key',p.key,
   'title',case when p.kind<>'private_estimate'then p.title when v.id is null then d.title else v.content->>'title'end,
   'client',case when p.kind<>'private_estimate'then p.client when v.id is null then d.client_snapshot->>'name'else v.content->'customer'->>'name'end,
   'clientId',p.client_id,'status',p.status,
   'currency',case when p.kind<>'private_estimate'then p.currency when v.id is null then d.currency else v.content->>'currency'end,
   'totalCents',case when p.kind<>'private_estimate'then p.total_cents when v.id is null then d.total_cents::numeric else(v.content->>'totalCents')::numeric end,
   'at',p.at)||case when p.kind='private_estimate'then jsonb_build_object('publication',p.publication,'draft',p.draft)else '{}'::jsonb end order by p.at desc,p.key asc),'[]'::jsonb),
  (p_after is null or exists(select 1 from filtered where at=p_after->>'at'and key=p_after->>'key'))into items,anchor_valid
 from page p left join pro_private_estimates d on p.kind='private_estimate'and d.owner_id=p_actor and d.id=p.private_estimate_id
 left join pro_private_estimate_publications v on v.id=p.private_publication_id and v.owner_id=p_actor;
 if not anchor_valid then raise exception 'Sales cursor changed'using errcode='40001';end if;
 if jsonb_array_length(items)>20 then cursor:=jsonb_build_object('at',items->19->>'at','key',items->19->>'key');items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',cursor);
end $$;
revoke all on function pro_private_estimate_sales_page(uuid,text,text,text,jsonb)from public,anon,authenticated;
grant execute on function pro_private_estimate_sales_page(uuid,text,text,text,jsonb)to service_role;
commit;
notify pgrst, 'reload schema';

-- ===== private-estimate-publication-copy-local.sql =====
-- LOCAL Pro only: a new private draft from an exact immutable shared version.
-- Current draft, publication decision/audience, ledger, inventory and work remain untouched.
begin;

create table if not exists public.pro_private_estimate_publication_copies (
  actor_id uuid not null references public.profiles(id) on delete cascade,
  action_id uuid not null,
  publication_id uuid not null references public.pro_private_estimate_publications(id) on delete cascade,
  source_estimate_id uuid not null,
  source_revision integer not null check(source_revision>0),
  target_estimate_id uuid not null,
  source_snapshot jsonb not null,
  input jsonb not null,
  result jsonb not null,
  at timestamptz not null default clock_timestamp(),
  primary key(actor_id,action_id),
  unique(actor_id,target_estimate_id),
  foreign key(actor_id,target_estimate_id)
    references public.pro_private_estimates(owner_id,id) on delete cascade
);

create or replace function public.pro_private_estimate_publication_copy_snapshot(
  p_actor uuid,
  p_publication uuid
) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare
  publication public.pro_private_estimate_publications;
  historical jsonb;
  snapshot jsonb;
  projected jsonb;
  lines jsonb;
begin
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then
    raise exception 'Forbidden' using errcode='42501';
  end if;
  select * into publication
    from public.pro_private_estimate_publications
    where owner_id=p_actor and id=p_publication;
  if not found then
    raise exception 'Owned publication unavailable' using errcode='42501';
  end if;

  -- Exact revision uses pro_private_estimate_history_revision_lookup. It does not
  -- read the current draft or require a currently active origin/client/catalogue.
  select jsonb_agg(history.after_estimate) into historical
    from public.pro_private_estimate_history history
    where history.owner_id=p_actor
      and history.estimate_id=publication.estimate_id
      and (history.after_estimate->>'revision')::integer=publication.estimate_revision;
  if jsonb_array_length(coalesce(historical,'[]'::jsonb))<>1 then
    raise exception 'Historical estimate unavailable' using errcode='40001';
  end if;
  snapshot:=historical->0;
  if snapshot->>'id' is distinct from publication.estimate_id::text
    or snapshot->>'ownerId' is distinct from p_actor::text
    or snapshot->>'clientId' is distinct from publication.client_id
    or snapshot->'revision' is distinct from to_jsonb(publication.estimate_revision)
  then
    raise exception 'Historical estimate identity changed' using errcode='40001';
  end if;

  select jsonb_agg(jsonb_build_object(
    'id',value->'id','description',value->'description','unit',value->'unit',
    'qtyMilli',value->'qtyMilli','unitPriceCents',value->'unitPriceCents',
    'discountBps',value->'discountBps','taxBps',value->'taxBps'
  )||jsonb_strip_nulls(jsonb_build_object('group',value->'group')) /* launch fix 2026-11-17: keep the line section */ order by ordinal) into lines
    from jsonb_array_elements(snapshot->'lines') with ordinality entry(value,ordinal);
  projected:=jsonb_build_object(
    'title',snapshot->'title','currency',snapshot->'currency',
    'validUntil',snapshot->'validUntil','notes',snapshot->'notes',
    'issuer',jsonb_build_object(
      'issuerName',snapshot->'issuer'->'issuerName',
      'issuerIdType',snapshot->'issuer'->'issuerIdType',
      'issuerId',snapshot->'issuer'->'issuerId',
      'issuerEmail',snapshot->'issuer'->'issuerEmail',
      'issuerPhone',snapshot->'issuer'->'issuerPhone',
      'issuerAddress',snapshot->'issuer'->'issuerAddress'
    ),
    'customer',jsonb_build_object(
      'name',snapshot->'client'->'name','tradeName',snapshot->'client'->'tradeName',
      'identification',snapshot->'client'->'identification','address',snapshot->'client'->'address'
    ),
    'lines',lines,'subtotalCents',snapshot->'subtotalCents',
    'discountCents',snapshot->'discountCents','taxCents',snapshot->'taxCents',
    'totalCents',snapshot->'totalCents'
  );
  if projected is distinct from publication.content then
    raise exception 'Historical shared content changed' using errcode='40001';
  end if;
  return jsonb_build_object(
    'publication',jsonb_build_object(
      'publicationId',publication.id,'estimateId',publication.estimate_id,
      'version',publication.version,'estimateRevision',publication.estimate_revision,
      'contentHash',publication.content_hash
    ),
    'snapshot',snapshot
  );
end $$;

create or replace function public.pro_private_estimate_publication_copy_mutate(
  p_actor uuid,
  p_input jsonb
) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare
  copy_action_id uuid;
  copy_publication_id uuid;
  copy_target_id uuid;
  prior public.pro_private_estimate_publication_copies;
  evidence jsonb;
  snapshot jsonb;
  target public.pro_private_estimates;
  line jsonb;
  line_position integer:=0;
  totals jsonb;
  result jsonb;
begin
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then
    raise exception 'Forbidden' using errcode='42501';
  end if;
  if jsonb_typeof(p_input) is distinct from 'object'
    or (select array_agg(key order by key) from jsonb_object_keys(p_input) key)
      is distinct from array['action','actionId','contentHash','estimateRevision','publicationId','targetEstimateId','version']
    or p_input->>'action' is distinct from 'copy_from_publication'
    or jsonb_typeof(p_input->'actionId') is distinct from 'string'
    or jsonb_typeof(p_input->'publicationId') is distinct from 'string'
    or jsonb_typeof(p_input->'targetEstimateId') is distinct from 'string'
    or jsonb_typeof(p_input->'version') is distinct from 'number'
    or jsonb_typeof(p_input->'estimateRevision') is distinct from 'number'
    or not coalesce(p_input->>'version'~'^[0-9]{1,10}$',false)
    or not coalesce(p_input->>'estimateRevision'~'^[0-9]{1,10}$',false)
    or (p_input->>'version')::numeric not between 1 and 2147483647
    or (p_input->>'estimateRevision')::numeric not between 1 and 2147483647
    or jsonb_typeof(p_input->'contentHash') is distinct from 'string'
    or not coalesce(p_input->>'contentHash'~'^[a-f0-9]{64}$',false)
  then
    raise exception 'Invalid publication copy' using errcode='22023';
  end if;
  copy_action_id:=(p_input->>'actionId')::uuid;
  copy_publication_id:=(p_input->>'publicationId')::uuid;
  copy_target_id:=(p_input->>'targetEstimateId')::uuid;
  if copy_action_id is null or copy_publication_id is null or copy_target_id is null then
    raise exception 'Invalid copy identity' using errcode='22023';
  end if;

  -- Same owner/action order as private-estimate writers. No publication/state/
  -- source-estimate row lock: A is immutable and B must not be rewound or edited.
  perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
  perform pg_advisory_xact_lock(hashtextextended(
    'pro-private-estimate-action:'||p_actor::text||':'||copy_action_id::text,0
  ));
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then
    raise exception 'Forbidden' using errcode='42501';
  end if;
  select * into prior from public.pro_private_estimate_publication_copies
    where actor_id=p_actor and action_id=copy_action_id;
  if found then
    if prior.input is distinct from p_input then
      raise exception 'Publication copy action reused' using errcode='40001';
    end if;
    if not exists(select 1 from public.pro_private_estimates
      where owner_id=p_actor and id=prior.target_estimate_id)
    then
      raise exception 'Copied estimate unavailable' using errcode='42501';
    end if;
    return prior.result;
  end if;

  -- Shared audit PK blocks the reverse collision through old private writers.
  -- The new receipt never pretends to be an old private-estimate mutation.
  if exists(select 1 from public.pro_private_estimate_actions
      where actor_id=p_actor and action_id=copy_action_id)
    or exists(select 1 from public.pro_private_estimate_history
      where owner_id=p_actor and action_id=copy_action_id)
    or exists(select 1 from public.pro_private_estimates
      where owner_id=p_actor and id=copy_target_id)
  then
    raise exception 'Copy action or target already exists' using errcode='40001';
  end if;
  evidence:=public.pro_private_estimate_publication_copy_snapshot(p_actor,copy_publication_id);
  if evidence->'publication'->'version' is distinct from p_input->'version'
    or evidence->'publication'->'estimateRevision' is distinct from p_input->'estimateRevision'
    or evidence->'publication'->>'contentHash' is distinct from p_input->>'contentHash'
    or evidence->'publication'->>'estimateId'=copy_target_id::text
  then
    raise exception 'Selected shared version changed' using errcode='40001';
  end if;
  snapshot:=evidence->'snapshot';
  if not exists(select 1 from public.pro_clients
    where user_id=p_actor and id=snapshot->>'clientId')
  then
    raise exception 'Historical customer unavailable' using errcode='40001';
  end if;
  totals:=public.pro_private_estimate_totals(snapshot->'lines');
  if totals is distinct from jsonb_build_object(
    'subtotalCents',snapshot->'subtotalCents','discountCents',snapshot->'discountCents',
    'taxCents',snapshot->'taxCents','totalCents',snapshot->'totalCents'
  ) then
    raise exception 'Historical estimate total changed' using errcode='40001';
  end if;
  insert into public.pro_private_estimates(
    owner_id,id,client_id,client_snapshot,source,issuer,title,notes,currency,valid_until,
    subtotal_cents,discount_cents,tax_cents,total_cents,revision,archived,created_at,updated_at
  ) values(
    p_actor,copy_target_id,snapshot->>'clientId',snapshot->'client',snapshot->'source',
    snapshot->'issuer',snapshot->>'title',snapshot->>'notes',snapshot->>'currency',
    (snapshot->>'validUntil')::date,(snapshot->>'subtotalCents')::bigint,
    (snapshot->>'discountCents')::bigint,(snapshot->>'taxCents')::bigint,
    (snapshot->>'totalCents')::bigint,1,false,clock_timestamp(),clock_timestamp()
  ) returning * into target;
  for line in select value from jsonb_array_elements(snapshot->'lines') loop
    line_position:=line_position+1;
    insert into public.pro_private_estimate_items
      values(p_actor,copy_target_id,(line->>'id')::uuid,line_position,line);
  end loop;
  result:=jsonb_build_object(
    'action','copy_from_publication','publication',evidence->'publication',
    'estimate',public.pro_private_estimate_json(target)
  );
  insert into public.pro_private_estimate_history(
    owner_id,estimate_id,action_id,action,before_estimate,after_estimate
  ) values(p_actor,copy_target_id,copy_action_id,'duplicate',snapshot,result->'estimate');
  insert into public.pro_private_estimate_publication_copies(
    actor_id,action_id,publication_id,source_estimate_id,source_revision,
    target_estimate_id,source_snapshot,input,result
  ) values(
    p_actor,copy_action_id,copy_publication_id,(evidence->'publication'->>'estimateId')::uuid,
    (evidence->'publication'->>'estimateRevision')::integer,copy_target_id,snapshot,p_input,result
  );
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then
    raise exception 'Forbidden' using errcode='42501';
  end if;
  return result;
end $$;

create or replace function public.pro_private_estimate_publication_copy_read(
  p_actor uuid,
  p_action uuid
) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare
  receipt public.pro_private_estimate_publication_copies;
begin
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then
    raise exception 'Forbidden' using errcode='42501';
  end if;
  select * into receipt from public.pro_private_estimate_publication_copies
    where actor_id=p_actor and action_id=p_action;
  if not found then return jsonb_build_object('receipt',null);end if;
  if not exists(select 1 from public.pro_private_estimates
    where owner_id=p_actor and id=receipt.target_estimate_id)
  then
    raise exception 'Copied estimate unavailable' using errcode='42501';
  end if;
  return jsonb_build_object('receipt',jsonb_build_object(
    'input',receipt.input,'result',receipt.result
  ));
end $$;

create or replace function public.pro_private_estimate_publication_copy_immutable()
returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin
  if tg_op='DELETE' and not exists(select 1 from public.profiles where id=old.actor_id) then
    return old;
  end if;
  raise exception 'Immutable publication copy provenance' using errcode='23514';
end $$;

drop trigger if exists pro_private_estimate_publication_copy_immutable
  on public.pro_private_estimate_publication_copies;
create trigger pro_private_estimate_publication_copy_immutable
  before update or delete on public.pro_private_estimate_publication_copies
  for each row execute function public.pro_private_estimate_publication_copy_immutable();

alter table public.pro_private_estimate_publication_copies enable row level security;
revoke all on public.pro_private_estimate_publication_copies from public,anon,authenticated;
grant all on public.pro_private_estimate_publication_copies to service_role;
revoke all on function public.pro_private_estimate_publication_copy_snapshot(uuid,uuid),
  public.pro_private_estimate_publication_copy_mutate(uuid,jsonb),
  public.pro_private_estimate_publication_copy_read(uuid,uuid),
  public.pro_private_estimate_publication_copy_immutable() from public,anon,authenticated;
grant execute on function public.pro_private_estimate_publication_copy_snapshot(uuid,uuid),
  public.pro_private_estimate_publication_copy_mutate(uuid,jsonb),
  public.pro_private_estimate_publication_copy_read(uuid,uuid),
  public.pro_private_estimate_publication_copy_immutable() to service_role;
commit;
notify pgrst, 'reload schema';

-- ===== work-budget-local.sql =====
-- LOCAL Pro only. Owner-private CRC budget/classification, never a money or stock writer.
-- Old material/time/expense events remain authoritative. Unknown labor is not zero.
-- Lock order: own action advisory -> own work-budget advisory -> own state row.
-- No old work/source/expense locks: avoids cycles with material, booking and expense writers.
begin;

create unique index if not exists pro_work_budget_work_identity on public.pro_work(user_id,id,"clientId");
create table if not exists public.pro_work_budget_state (
  owner_id uuid not null references public.profiles(id) on delete cascade,
  work_id text not null,client_id text not null,revision integer not null check(revision>0),
  primary key(owner_id,work_id),
  foreign key(owner_id,work_id,client_id) references public.pro_work(user_id,id,"clientId") on delete cascade
);
create table if not exists public.pro_work_budget_codes (
  owner_id uuid not null,work_id text not null,id uuid not null,
  kind text not null check(kind in('group','item')),
  code text not null check(code ~ '^[A-Z0-9][A-Z0-9._-]{0,29}$'),
  title text not null check(length(btrim(title)) between 1 and 160),parent_id uuid,
  planned_cents bigint check(planned_cents between 0 and 9000000000000),
  archived boolean not null default false,
  primary key(owner_id,work_id,id),unique(owner_id,work_id,code),
  foreign key(owner_id,work_id) references public.pro_work_budget_state(owner_id,work_id) on delete cascade,
  foreign key(owner_id,work_id,parent_id) references public.pro_work_budget_codes(owner_id,work_id,id),
  check((kind='group' and parent_id is null and planned_cents is null)
    or(kind='item' and planned_cents is not null)),check(parent_id is distinct from id)
);
create table if not exists public.pro_work_budget_assignments (
  owner_id uuid not null,work_id text not null,kind text not null check(kind in('material','time','expense')),
  source_id uuid not null,code_id uuid,
  primary key(owner_id,work_id,kind,source_id),
  foreign key(owner_id,work_id) references public.pro_work_budget_state(owner_id,work_id) on delete cascade,
  foreign key(owner_id,work_id,code_id) references public.pro_work_budget_codes(owner_id,work_id,id)
);
create table if not exists public.pro_work_budget_actions (
  owner_id uuid not null references public.profiles(id) on delete cascade,
  action_id uuid not null,work_id text not null,revision integer not null,
  input jsonb not null,before_value jsonb,result jsonb not null,context_json jsonb,
  at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id),
  unique(owner_id,work_id,revision),
  foreign key(owner_id,work_id) references public.pro_work_budget_state(owner_id,work_id) on delete cascade
);
create index if not exists pro_work_budget_codes_page on public.pro_work_budget_codes(owner_id,work_id,id);
create index if not exists pro_work_budget_actions_page on public.pro_work_budget_actions(owner_id,work_id,revision desc);

create or replace function public.pro_work_budget_context(p_actor uuid,p_work text)
returns jsonb language plpgsql volatile security invoker set search_path=public,pg_temp as $$
declare context jsonb;
begin
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then
    raise exception 'Forbidden' using errcode='42501';
  end if;
  select jsonb_build_object('id',w.id,'clientId',c.id,'title',w.service,
    'cancelled',w.cancelled,'clientArchived',c.archived) into context
    from public.pro_work w join public.pro_clients c on c.user_id=w.user_id and c.id=w."clientId"
    where w.user_id=p_actor and w.id=p_work;
  if context is null then raise exception 'Owned work unavailable' using errcode='42501';end if;
  if exists(select 1 from public.pro_work_budget_state s where s.owner_id=p_actor
    and s.work_id=p_work and s.client_id is distinct from context->>'clientId') then
    raise exception 'Budget customer changed' using errcode='42501';
  end if;
  return context;
end $$;

create or replace function public.pro_work_budget_code_json(p_code public.pro_work_budget_codes)
returns jsonb language sql immutable security invoker set search_path=public,pg_temp as $$
  select jsonb_build_object('id',p_code.id,'kind',p_code.kind,'code',p_code.code,
    'title',p_code.title,'parentId',p_code.parent_id,'plannedCents',p_code.planned_cents,'archived',p_code.archived)
$$;

create or replace function public.pro_work_budget_sources(p_actor uuid,p_work text)
returns table(kind text,id uuid,fingerprint text,title text,recorded_on date,amount_cents bigint,
  minutes bigint,unknown_minutes bigint,code_id uuid)
language sql stable security invoker set search_path=public,pg_temp as $$
  with facts as (
    select 'material'::text kind,e.id,e.label title,
      (e.created_at at time zone 'America/Costa_Rica')::date recorded_on,
      (round(e.quantity*e.unit_cost,2)*100)::bigint amount_cents,
      null::bigint minutes,0::bigint unknown_minutes,
      jsonb_build_object('id',e.id,'kind','material','quantity',e.quantity,'unitCost',e.unit_cost,
        'productId',e.product_id,'label',e.label,'at',e.created_at) fact
      from public.pro_client_entries e where e.user_id=p_actor and e.work_id=p_work
        and e.kind='material' and not exists(select 1 from public.pro_client_entries r
          where r.user_id=e.user_id and r.reversal_id=e.id)
    union all
    select 'time',e.id,e.note,e.recorded_on,e.amount_cents,e.minutes::bigint,
      case when e.hourly_cost_cents is null then e.minutes else 0 end::bigint,
      jsonb_build_object('id',e.id,'kind','time','minutes',e.minutes,'rate',e.hourly_cost_cents,
        'amount',e.amount_cents,'date',e.recorded_on,'note',e.note,'at',e.created_at)
      from public.pro_work_cost_entries e where e.user_id=p_actor and e.work_id=p_work
        and e.kind='time' and not exists(select 1 from public.pro_work_cost_entries r
          where r.user_id=e.user_id and r.reversal_id=e.id)
    union all
    select 'expense',a.entry_id,e.concept,e.expense_date,e.amount_cents,null::bigint,0::bigint,
      jsonb_build_object('id',a.entry_id,'kind','expense','expenseId',e.id,'amount',e.amount_cents,
        'date',e.expense_date,'concept',e.concept,'supplier',e.supplier_name)
      from public.pro_work_expense_assignments a join public.pro_internal_expenses e
        on e.user_id=a.user_id and e.id=a.expense_id
      where a.user_id=p_actor and a.work_id=p_work
  ) select f.kind,f.id,md5(f.fact::text),f.title,f.recorded_on,f.amount_cents,f.minutes,
      f.unknown_minutes,a.code_id
    from facts f left join public.pro_work_budget_assignments a
      on a.owner_id=p_actor and a.work_id=p_work and a.kind=f.kind and a.source_id=f.id
$$;

create or replace function public.pro_work_budget_totals(
  p_planned bigint,p_actual bigint,p_minutes bigint,p_unknown bigint,p_sources bigint
) returns jsonb language sql immutable security invoker set search_path=public,pg_temp as $$
  select jsonb_build_object('plannedCents',p_planned,'actualCents',p_actual,
    'unknownMinutes',p_minutes,'unknownCount',p_unknown,'sourceCount',p_sources,
    'varianceCents',case when p_planned is null or p_unknown>0 then null else p_planned-p_actual end)
$$;

create or replace function public.pro_work_budget_frame(p_actor uuid,p_work text)
returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare context jsonb;rev integer;metadata text;source_hash text;answer jsonb;
begin
  context:=public.pro_work_budget_context(p_actor,p_work);
  rev:=coalesce((select revision from public.pro_work_budget_state where owner_id=p_actor and work_id=p_work),0);
  select md5(jsonb_build_object(
    'revision',rev,'workId',p_work,'clientId',context->>'clientId',
    'codes',coalesce((select jsonb_agg(public.pro_work_budget_code_json(c) order by id)
      from public.pro_work_budget_codes c where owner_id=p_actor and work_id=p_work),'[]'::jsonb),
    'assignments',coalesce((select jsonb_agg(jsonb_build_array(kind,source_id,code_id) order by kind,source_id)
      from public.pro_work_budget_assignments where owner_id=p_actor and work_id=p_work),'[]'::jsonb)
  )::text) into metadata;
  with sources as materialized(select * from public.pro_work_budget_sources(p_actor,p_work))
  select md5(jsonb_build_object('owner',p_actor,'work',p_work,
    'sources',coalesce((select jsonb_agg(jsonb_build_array(kind,id,fingerprint) order by kind,id) from sources),'[]'::jsonb))::text),
    jsonb_build_object(
      'work',context,'currency','CRC','revision',rev,'metadataFingerprint',metadata,
      'suggestedItemCode',(select lpad(n::text,3,'0')from generate_series(1,501)n where not exists(select 1 from public.pro_work_budget_codes c where c.owner_id=p_actor and c.work_id=p_work and c.code=lpad(n::text,3,'0'))order by n limit 1),
      'suggestedGroupCode',(select 'G'||lpad(n::text,3,'0')from generate_series(1,501)n where not exists(select 1 from public.pro_work_budget_codes c where c.owner_id=p_actor and c.work_id=p_work and c.code='G'||lpad(n::text,3,'0'))order by n limit 1),
      'canWrite',not(context->>'cancelled')::boolean and not(context->>'clientArchived')::boolean,
      'codeCount',(select count(*) from public.pro_work_budget_codes where owner_id=p_actor and work_id=p_work),
      'summary',public.pro_work_budget_totals(
        (select sum(planned_cents)::bigint from public.pro_work_budget_codes where owner_id=p_actor and work_id=p_work and kind='item'),
        coalesce(sum(amount_cents),0)::bigint,coalesce(sum(unknown_minutes),0)::bigint,
        count(*) filter(where amount_cents is null),count(*)),
      'unassigned',public.pro_work_budget_totals(null,
        coalesce(sum(amount_cents) filter(where code_id is null),0)::bigint,
        coalesce(sum(unknown_minutes) filter(where code_id is null),0)::bigint,
        count(*) filter(where code_id is null and amount_cents is null),count(*) filter(where code_id is null))
    ) into source_hash,answer from sources;
  return answer||jsonb_build_object('sourceFingerprint',source_hash,'fingerprint',md5(metadata||source_hash));
end $$;

create or replace function public.pro_work_budget_read(
  p_actor uuid,p_work text,p_view text default 'overview',p_status text default 'all',
  p_query text default '',p_code text default null,p_kind text default null,
  p_after text default null,p_revision integer default null,p_fingerprint text default null
) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare frame jsonb;answer jsonb;cursor_revision integer;
begin
  frame:=public.pro_work_budget_frame(p_actor,p_work);
  if p_view='overview' then return frame;end if;
  if p_view not in('codes','code','costs','cost','history') or p_status not in('all','active','archived')
    or p_query is null or length(p_query)>160
    or(p_kind is not null and(p_view in('codes','code')and p_kind not in('group','item')or p_view in('costs','cost')and p_kind not in('material','time','expense'))) then
    raise exception 'Invalid budget query' using errcode='22023';
  end if;
  if p_view='cost'then
    if p_kind is null or p_code is null then raise exception 'Cost identity required'using errcode='22023';end if;
    select jsonb_build_object('workId',p_work,'revision',frame->'revision','fingerprint',frame->'fingerprint',
      'item',(select jsonb_build_object('kind',s.kind,'id',s.id,'fingerprint',s.fingerprint,
        'title',s.title,'date',s.recorded_on,'amountCents',s.amount_cents,'minutes',s.minutes,
        'unknownMinutes',s.unknown_minutes,'codeId',s.code_id,
        'code',case when c.id is null then null else public.pro_work_budget_code_json(c)end)
      from public.pro_work_budget_sources(p_actor,p_work)s left join public.pro_work_budget_codes c
        on c.owner_id=p_actor and c.work_id=p_work and c.id=s.code_id
      where s.kind=p_kind and s.id=p_code::uuid))into answer;
    return answer;
  end if;
  if p_view='history' then
    if p_after is not null then
      select revision into cursor_revision from public.pro_work_budget_actions
        where owner_id=p_actor and work_id=p_work and action_id=p_after::uuid;
      if not found then raise exception 'History cursor unavailable' using errcode='40001';end if;
    end if;
    with matches as materialized(select * from public.pro_work_budget_actions
      where owner_id=p_actor and work_id=p_work and(p_after is null or revision<cursor_revision)
      order by revision desc limit 21),page as(select * from matches order by revision desc limit 20)
    select jsonb_build_object('workId',p_work,'items',coalesce((select jsonb_agg(jsonb_build_object(
      'actionId',action_id,'at',at,'input',input,'before',before_value,'result',result,'context',context_json) order by revision desc)from page),'[]'::jsonb),
      'nextCursor',case when(select count(*)from matches)>20 then(select action_id from page order by revision limit 1)else null end)into answer;
    return answer;
  end if;
  if(p_after is null and(p_revision is not null or p_fingerprint is not null))or(p_after is not null and(p_revision is null or p_fingerprint is null))then
    raise exception 'Incomplete page snapshot' using errcode='22023';
  end if;
  if p_after is not null and(p_revision is distinct from(frame->>'revision')::integer
    or p_fingerprint is distinct from frame->>'fingerprint')then
    raise exception 'Budget or actual costs changed' using errcode='40001';
  end if;
  if p_view in('codes','code') then
    if p_after is not null and not exists(select 1 from public.pro_work_budget_codes c
      where c.owner_id=p_actor and c.work_id=p_work and c.id=p_after::uuid
      and(p_status='all' or c.archived=(p_status='archived'))and(p_kind is null or c.kind=p_kind)
      and(p_query='' or strpos(lower(c.code||' '||c.title),lower(p_query))>0))then
      raise exception 'Code cursor unavailable'using errcode='40001';
    end if;
    with matches as materialized(select * from public.pro_work_budget_codes c where owner_id=p_actor and work_id=p_work
      and(p_status='all' or archived=(p_status='archived'))and(p_kind is null or kind=p_kind)and(p_view<>'code'or id=p_code::uuid)and(p_query='' or strpos(lower(code||' '||title),lower(p_query))>0)
      and(p_after is null or(code,id)>(select code,id from public.pro_work_budget_codes where owner_id=p_actor and work_id=p_work and id=p_after::uuid))order by code,id limit 21),
    page as(select * from matches order by code,id limit 20),
    sources as materialized(select * from public.pro_work_budget_sources(p_actor,p_work)),
    members as(select p.id target,c.id member,c.planned_cents from page p join public.pro_work_budget_codes c
      on c.owner_id=p.owner_id and c.work_id=p.work_id and c.kind='item' and(c.id=p.id or c.parent_id=p.id)),
    planned as(select target,sum(planned_cents)::bigint planned from members group by target),
    actual as(select m.target,coalesce(sum(s.amount_cents),0)::bigint actual,
      coalesce(sum(s.unknown_minutes),0)::bigint minutes,count(*)filter(where s.amount_cents is null)unknown,count(*)sources
      from members m join sources s on s.code_id=m.member group by m.target)
    select jsonb_build_object('workId',p_work,'revision',frame->'revision','fingerprint',frame->'fingerprint',
      'items',coalesce((select jsonb_agg(jsonb_build_object('code',public.pro_work_budget_code_json(p),'parent',case when parent.id is null then null else public.pro_work_budget_code_json(parent)end,
        'totals',public.pro_work_budget_totals(b.planned,coalesce(a.actual,0),coalesce(a.minutes,0),coalesce(a.unknown,0),coalesce(a.sources,0)))order by p.code,p.id)
        from page p left join public.pro_work_budget_codes parent on parent.owner_id=p.owner_id and parent.work_id=p.work_id and parent.id=p.parent_id left join planned b on b.target=p.id left join actual a on a.target=p.id),'[]'::jsonb),
      'nextCursor',case when(select count(*)from matches)>20 then(select id from page order by code desc,id desc limit 1)else null end)into answer;
    if p_view='code'then
      if jsonb_array_length(answer->'items')<>1 then raise exception 'Budget code unavailable'using errcode='P0002';end if;
      answer:=(answer-'items'-'nextCursor')||(answer->'items'->0);
    end if;
  else
    if p_code is not null and p_code<>'unassigned' and not exists(select 1 from public.pro_work_budget_codes
      where owner_id=p_actor and work_id=p_work and id=p_code::uuid)then
      raise exception 'Budget code unavailable'using errcode='40001';
    end if;
    with sources as materialized(select * from public.pro_work_budget_sources(p_actor,p_work)),
    eligible as materialized(select * from sources s where(p_kind is null or s.kind=p_kind)
      and(p_code is null or p_code='unassigned'and s.code_id is null or s.code_id::text=p_code
        or exists(select 1 from public.pro_work_budget_codes c where c.owner_id=p_actor and c.work_id=p_work and c.id=s.code_id and c.parent_id::text=p_code))
      and(p_query='' or strpos(lower(s.title),lower(p_query))>0)),
    matches as materialized(select * from eligible where p_after is null or kind||':'||id::text>p_after order by kind,id limit 21),
    page as(select * from matches order by kind,id limit 20)
    select jsonb_build_object('workId',p_work,'revision',frame->'revision','fingerprint',frame->'fingerprint',
      'items',coalesce((select jsonb_agg(jsonb_build_object('kind',page.kind,'id',page.id,'fingerprint',page.fingerprint,
        'title',page.title,'date',recorded_on,'amountCents',amount_cents,'minutes',minutes,'unknownMinutes',unknown_minutes,'codeId',code_id,'code',case when c.id is null then null else public.pro_work_budget_code_json(c)end)order by page.kind,page.id)from page left join public.pro_work_budget_codes c on c.owner_id=p_actor and c.work_id=p_work and c.id=page.code_id),'[]'::jsonb),
      'nextCursor',case when(select count(*)from matches)>20 then(select kind||':'||id::text from page order by kind desc,id desc limit 1)else null end,
      'anchorValid',p_after is null or exists(select 1 from eligible where kind||':'||id::text=p_after))into answer;
    if not(answer->>'anchorValid')::boolean then raise exception 'Cost cursor unavailable'using errcode='40001';end if;
    answer:=answer-'anchorValid';
  end if;
  return answer;
end $$;

create or replace function public.pro_work_budget_mutate(p_actor uuid,p_input jsonb)
returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare
  act text;aid uuid;wid text;cid uuid;pid uuid;keys text[];rev integer;current_rev integer;
  context jsonb;prior public.pro_work_budget_actions;code_row public.pro_work_budget_codes;
  before_json jsonb;assignment_json jsonb;history_context jsonb;source_row record;result_json jsonb;frame jsonb;
begin
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)then
    raise exception 'Forbidden'using errcode='42501';
  end if;
  if jsonb_typeof(p_input)is distinct from'object' or jsonb_typeof(p_input->'action')is distinct from'string'
    or jsonb_typeof(p_input->'actionId')is distinct from'string' or jsonb_typeof(p_input->'workId')is distinct from'string'
    or jsonb_typeof(p_input->'clientId')is distinct from'string'
    or jsonb_typeof(p_input->'revision')is distinct from'number'
    or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false)
    or(p_input->>'revision')::numeric not between 0 and 2147483646 then
    raise exception 'Invalid budget mutation'using errcode='22023';
  end if;
  act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;wid:=p_input->>'workId';rev:=(p_input->>'revision')::integer;
  keys:=array['action','actionId','clientId','workId','revision']||case act
    when'save_group'then array['id','code','title']when'save_item'then array['id','code','title','parentId','plannedCents']
    when'archive'then array['id']when'restore'then array['id']when'assign'then array['source','codeId']else null end;
  if keys is null or not(p_input?&keys)or(p_input-keys)<>'{}'::jsonb or length(wid)not between 1 and 160 or aid is null then
    raise exception 'Invalid budget fields'using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('pro-work-budget-action:'||p_actor::text||':'||aid::text,0));
  perform pg_advisory_xact_lock(hashtextextended('pro-work-budget:'||p_actor::text||':'||wid,0));
  context:=public.pro_work_budget_context(p_actor,wid);
  if context->>'clientId'is distinct from p_input->>'clientId'then raise exception 'Work customer changed'using errcode='40001';end if;
  select * into prior from public.pro_work_budget_actions where owner_id=p_actor and action_id=aid;
  if found then
    if prior.input is distinct from p_input then raise exception 'Budget action reused'using errcode='40001';end if;
    return prior.result;
  end if;
  if(context->>'cancelled')::boolean or(context->>'clientArchived')::boolean then
    raise exception 'Restore work or customer before changing budget'using errcode='40001';
  end if;
  select revision into current_rev from public.pro_work_budget_state where owner_id=p_actor and work_id=wid for update;
  if coalesce(current_rev,0)<>rev then raise exception 'Budget changed'using errcode='40001';end if;
  if current_rev is null then
    insert into public.pro_work_budget_state values(p_actor,wid,context->>'clientId',1);
  else update public.pro_work_budget_state set revision=revision+1 where owner_id=p_actor and work_id=wid;end if;
  if act='assign' then
    if jsonb_typeof(p_input->'source')is distinct from'object'
      or(select array_agg(key order by key)from jsonb_object_keys(p_input->'source')key)is distinct from array['fingerprint','id','kind']
      or jsonb_typeof(p_input->'source'->'id')is distinct from'string'
      or jsonb_typeof(p_input->'source'->'kind')is distinct from'string'
      or jsonb_typeof(p_input->'source'->'fingerprint')is distinct from'string'
      or not coalesce(p_input->'source'->>'fingerprint'~'^[a-f0-9]{32}$',false)
      or coalesce(p_input->'source'->>'kind','')not in('material','time','expense')
      or jsonb_typeof(p_input->'codeId')not in('null','string')then
      raise exception 'Invalid cost assignment'using errcode='22023';
    end if;
    cid:=(p_input->>'codeId')::uuid;
    if cid is not null and not exists(select 1 from public.pro_work_budget_codes c
      where c.owner_id=p_actor and c.work_id=wid and c.id=cid and c.kind='item'and not c.archived
      and(c.parent_id is null or exists(select 1 from public.pro_work_budget_codes p
        where p.owner_id=p_actor and p.work_id=wid and p.id=c.parent_id and p.kind='group'and not p.archived)))then
      raise exception 'Choose an active budget item'using errcode='40001';
    end if;
    -- One SPI statement validates current active identity/facts after all own locks.
    -- Later legacy edits are legitimate and reflected by fresh derived reads.
    select * into source_row from public.pro_work_budget_sources(p_actor,wid)
      where kind=p_input->'source'->>'kind'and id=(p_input->'source'->>'id')::uuid;
    if not found or source_row.fingerprint is distinct from p_input->'source'->>'fingerprint'then
      raise exception 'Actual cost changed'using errcode='40001';
    end if;
    select jsonb_build_object('kind',kind,'id',source_id,'codeId',code_id)into before_json
      from public.pro_work_budget_assignments where owner_id=p_actor and work_id=wid
      and kind=source_row.kind and source_id=source_row.id;
    before_json:=coalesce(before_json,jsonb_build_object('kind',source_row.kind,'id',source_row.id,'codeId',null));
    history_context:=jsonb_build_object(
      'source',jsonb_build_object('kind',source_row.kind,'id',source_row.id,'title',source_row.title,
        'date',source_row.recorded_on,'amountCents',source_row.amount_cents,'minutes',source_row.minutes),
      'fromCode',(select public.pro_work_budget_code_json(c)from public.pro_work_budget_codes c where c.owner_id=p_actor and c.work_id=wid and c.id=source_row.code_id),
      'toCode',(select public.pro_work_budget_code_json(c)from public.pro_work_budget_codes c where c.owner_id=p_actor and c.work_id=wid and c.id=cid)
    );
    insert into public.pro_work_budget_assignments values(p_actor,wid,source_row.kind,source_row.id,cid)
      on conflict(owner_id,work_id,kind,source_id)do update set code_id=excluded.code_id;
    assignment_json:=jsonb_build_object('kind',source_row.kind,'id',source_row.id,'codeId',cid);
  else
    if jsonb_typeof(p_input->'id')is distinct from'string'then raise exception 'Invalid code identity'using errcode='22023';end if;
    cid:=(p_input->>'id')::uuid;
    select * into code_row from public.pro_work_budget_codes where owner_id=p_actor and work_id=wid and id=cid;
    if found then before_json:=public.pro_work_budget_code_json(code_row);end if;
    if act in('save_group','save_item')then
      if jsonb_typeof(p_input->'code')is distinct from'string'or not coalesce(p_input->>'code'~'^[A-Z0-9][A-Z0-9._-]{0,29}$',false)
        or jsonb_typeof(p_input->'title')is distinct from'string'or length(btrim(p_input->>'title'))not between 1 and 160
        or p_input->>'title'~'[[:cntrl:]]'then raise exception 'Invalid code content'using errcode='22023';end if;
      if code_row.id is not null and(code_row.archived or code_row.kind<>case when act='save_group'then'group'else'item'end)then
        raise exception 'Restore code or retain its kind'using errcode='40001';
      end if;
      if code_row.id is null and(select count(*)from public.pro_work_budget_codes where owner_id=p_actor and work_id=wid)>=500 then
        raise exception 'Budget code capacity reached'using errcode='54000';
      end if;
      if act='save_item'then
        if jsonb_typeof(p_input->'parentId')not in('null','string')or jsonb_typeof(p_input->'plannedCents')is distinct from'number'
          or not coalesce(p_input->>'plannedCents'~'^[0-9]{1,13}$',false)
          or(p_input->>'plannedCents')::numeric not between 0 and 9000000000000 then
          raise exception 'Invalid planned amount'using errcode='22023';end if;
        pid:=(p_input->>'parentId')::uuid;
        if pid is not null and not exists(select 1 from public.pro_work_budget_codes where owner_id=p_actor and work_id=wid
          and id=pid and kind='group'and not archived)then raise exception 'Choose active parent group'using errcode='40001';end if;
      end if;
      insert into public.pro_work_budget_codes(owner_id,work_id,id,kind,code,title,parent_id,planned_cents)
        values(p_actor,wid,cid,case when act='save_group'then'group'else'item'end,p_input->>'code',btrim(p_input->>'title'),pid,(p_input->>'plannedCents')::bigint)
        on conflict(owner_id,work_id,id)do update set code=excluded.code,title=excluded.title,parent_id=excluded.parent_id,planned_cents=excluded.planned_cents
        returning * into code_row;
    else
      if code_row.id is null or code_row.archived=(act='archive')then raise exception 'Code status changed'using errcode='40001';end if;
      if act='archive'and code_row.kind='group'and exists(select 1 from public.pro_work_budget_codes
        where owner_id=p_actor and work_id=wid and parent_id=cid and not archived)then
        raise exception 'Archive active children first'using errcode='40001';end if;
      if act='restore'and code_row.parent_id is not null and not exists(select 1 from public.pro_work_budget_codes
        where owner_id=p_actor and work_id=wid and id=code_row.parent_id and not archived)then
        raise exception 'Restore parent group first'using errcode='40001';end if;
      update public.pro_work_budget_codes set archived=(act='archive')where owner_id=p_actor and work_id=wid and id=cid returning * into code_row;
    end if;
  end if;
  frame:=public.pro_work_budget_frame(p_actor,wid);
  result_json:=jsonb_build_object('action',act,'workId',wid,'revision',rev+1,'metadataFingerprint',frame->'metadataFingerprint',
    'code',case when act='assign'then null else public.pro_work_budget_code_json(code_row)end,'assignment',assignment_json);
  insert into public.pro_work_budget_actions(owner_id,action_id,work_id,revision,input,before_value,result,context_json)
    values(p_actor,aid,wid,rev+1,p_input,before_json,result_json,history_context);
  context:=public.pro_work_budget_context(p_actor,wid);
  if(context->>'cancelled')::boolean or(context->>'clientArchived')::boolean then
    raise exception 'Work or customer changed'using errcode='40001';end if;
  return result_json;
end $$;

create or replace function public.pro_work_budget_action_read(p_actor uuid,p_action uuid)
returns jsonb language plpgsql volatile security invoker set search_path=public,pg_temp as $$
declare receipt public.pro_work_budget_actions;
begin
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden'using errcode='42501';end if;
  select * into receipt from public.pro_work_budget_actions where owner_id=p_actor and action_id=p_action;
  if not found then return jsonb_build_object('receipt',null);end if;
  perform public.pro_work_budget_context(p_actor,receipt.work_id);
  return jsonb_build_object('receipt',jsonb_build_object('input',receipt.input,'result',receipt.result));
end $$;

create or replace function public.pro_work_budget_immutable()
returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin
  if tg_op='DELETE'and not exists(select 1 from public.profiles where id=old.owner_id)then return old;end if;
  raise exception 'Immutable budget audit'using errcode='23514';
end $$;
create or replace function public.pro_work_budget_work_guard()
returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin
  if exists(select 1 from public.pro_work_budget_state where owner_id=old.user_id and work_id=old.id)then
    if tg_op='DELETE'then
      if not exists(select 1 from public.profiles where id=old.user_id)then return old;end if;
      raise exception 'Work has budget history'using errcode='23514';
    end if;
    if(new.user_id,new.id,new."clientId")is distinct from(old.user_id,old.id,old."clientId")then
      raise exception 'Budget work identity is immutable'using errcode='23514';end if;
  end if;
  if tg_op='DELETE'then return old;else return new;end if;
end $$;
drop trigger if exists pro_work_budget_immutable on public.pro_work_budget_actions;
create trigger pro_work_budget_immutable before update or delete on public.pro_work_budget_actions
  for each row execute function public.pro_work_budget_immutable();
drop trigger if exists pro_work_budget_work_guard on public.pro_work;
create trigger pro_work_budget_work_guard before update or delete on public.pro_work
  for each row execute function public.pro_work_budget_work_guard();
do $$declare t text;f record;begin
  foreach t in array array['pro_work_budget_state','pro_work_budget_codes','pro_work_budget_assignments','pro_work_budget_actions']loop
    execute format('alter table public.%I enable row level security',t);
    execute format('revoke all on public.%I from public,anon,authenticated',t);
    execute format('grant all on public.%I to service_role',t);
  end loop;
  for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public'and p.proname like'pro_work_budget_%'loop
    execute format('revoke all on function %s from public,anon,authenticated',f.signature);
    execute format('grant execute on function %s to service_role',f.signature);
  end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== private-estimate-destination-copy-local.sql =====
-- LOCAL Pro only. Copy saved commercial content to an explicitly reviewed destination.
-- No old function/table definition changes, publication decisions or financial writes.
-- Owner -> common old estimate-action advisory -> source/destination SHARE NOWAIT.
-- NOWAIT avoids the legacy booking work-row -> owner advisory inverse order.
begin;
create table if not exists public.pro_private_estimate_destination_copies (
  actor_id uuid not null references public.profiles(id) on delete cascade,
  action_id uuid not null,target_estimate_id uuid not null,
  source_kind text not null check(source_kind in('draft','publication')),
  source_estimate_id uuid not null,source_snapshot jsonb not null,
  destination_snapshot jsonb not null,input jsonb not null,result jsonb not null,
  at timestamptz not null default clock_timestamp(),primary key(actor_id,action_id),
  unique(actor_id,target_estimate_id),foreign key(actor_id,target_estimate_id)
    references public.pro_private_estimates(owner_id,id)on delete cascade
);

create or replace function public.pro_private_estimate_destination_copy_source(p_actor uuid,p_source jsonb)
returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare document public.pro_private_estimates;reference jsonb;evidence jsonb;keys text[];
begin
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden'using errcode='42501';end if;
  if jsonb_typeof(p_source)is distinct from'object'or jsonb_typeof(p_source->'kind')is distinct from'string'then
    raise exception 'Invalid estimate source'using errcode='22023';end if;
  select array_agg(key order by key)into keys from jsonb_object_keys(p_source)key;
  if p_source->>'kind'='draft'then
    if keys is distinct from array['estimateId','kind','revision']
      or jsonb_typeof(p_source->'estimateId')is distinct from'string'
      or jsonb_typeof(p_source->'revision')is distinct from'number'
      or not coalesce(p_source->>'revision'~'^[0-9]{1,10}$',false)
      or(p_source->>'revision')::numeric not between 1 and 2147483647 then
      raise exception 'Invalid saved source'using errcode='22023';end if;
    select * into document from public.pro_private_estimates where owner_id=p_actor and id=(p_source->>'estimateId')::uuid;
    if not found then raise exception 'Owned estimate unavailable'using errcode='42501';end if;
    if document.revision<>(p_source->>'revision')::integer then raise exception 'Saved source changed'using errcode='40001';end if;
    return jsonb_build_object('source',p_source,'estimate',public.pro_private_estimate_json(document));
  elsif p_source->>'kind'='publication'then
    if keys is distinct from array['contentHash','estimateRevision','kind','publicationId','version']
      or jsonb_typeof(p_source->'publicationId')is distinct from'string'
      or jsonb_typeof(p_source->'contentHash')is distinct from'string'
      or not coalesce(p_source->>'contentHash'~'^[a-f0-9]{64}$',false)
      or jsonb_typeof(p_source->'version')is distinct from'number'
      or jsonb_typeof(p_source->'estimateRevision')is distinct from'number'
      or not coalesce(p_source->>'version'~'^[0-9]{1,10}$',false)
      or not coalesce(p_source->>'estimateRevision'~'^[0-9]{1,10}$',false)
      or(p_source->>'version')::numeric not between 1 and 2147483647
      or(p_source->>'estimateRevision')::numeric not between 1 and 2147483647 then
      raise exception 'Invalid shared source'using errcode='22023';end if;
    evidence:=public.pro_private_estimate_publication_copy_snapshot(p_actor,(p_source->>'publicationId')::uuid);
    reference:=evidence->'publication';
    if reference->'version'is distinct from p_source->'version'
      or reference->'estimateRevision'is distinct from p_source->'estimateRevision'
      or reference->'contentHash'is distinct from p_source->'contentHash'then
      raise exception 'Shared source changed'using errcode='40001';end if;
    return jsonb_build_object('source',reference||jsonb_build_object('kind','publication'),'estimate',evidence->'snapshot');
  end if;
  raise exception 'Invalid source kind'using errcode='22023';
end $$;

create or replace function public.pro_private_estimate_destination_copy_context(
  p_actor uuid,p_client text default null,p_kind text default null,p_id text default null
)returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
  select jsonb_build_object('client',c.value->'client','clientFingerprint',c.value->'clientFingerprint','source',c.value->'source')
    from(select public.pro_private_estimate_context(p_actor,p_client,p_kind,p_id)value)c
$$;

create or replace function public.pro_private_estimate_destination_copy_options(
  p_actor uuid,p_kind text,p_query text default '',p_after text default null,p_fingerprint text default null
)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare answer jsonb;
begin
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden'using errcode='42501';end if;
  if p_kind is null or p_kind not in('client','work','manual')or p_query is null or length(p_query)>100
    or(p_after is null)is distinct from(p_fingerprint is null)then raise exception 'Invalid destination query'using errcode='22023';end if;
  with candidates as materialized(
    select c.id,c.name,c.id client_id,c.name client_name,md5(to_jsonb(c)::text)version,
      null::text advisory_date,false has_linked_work
      from public.pro_clients c where p_kind='client'and c.user_id=p_actor and not c.archived
    union all
    select w.id,w.service,w."clientId",c.name,md5(to_jsonb(w)::text),nullif(w.start,''),false
      from public.pro_work w join public.pro_clients c on c.user_id=w.user_id and c.id=w."clientId"
      where p_kind='work'and w.user_id=p_actor and not coalesce(w.cancelled,false)and not c.archived
    union all
    select l.id::text,l.title,l.client_id,c.name,l.revision::text,
      to_char(l.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),m.lead_id is not null
      from public.pro_lead_center_records l join public.pro_clients c on c.user_id=l.owner_id and c.id=l.client_id
      left join public.pro_manual_lead_works m on m.owner_id=l.owner_id and m.lead_id=l.id
      where p_kind='manual'and l.owner_id=p_actor and l.kind='manual'and not l.archived and not c.archived
  ),eligible as materialized(select * from candidates where p_query=''or strpos(lower(name||' '||client_name),lower(p_query))>0),
  token as(select md5(jsonb_build_object('owner',p_actor,'kind',p_kind,'query',p_query,
    'rows',coalesce(jsonb_agg(jsonb_build_array(id,name,client_id,client_name,version,advisory_date,has_linked_work)order by id),'[]'::jsonb))::text)value from eligible),
  matches as materialized(select * from eligible where p_after is null or id>p_after order by id limit 21),
  page as(select * from matches order by id limit 20)
  select jsonb_build_object('fingerprint',(select value from token),
    'items',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name,'clientId',client_id,'clientName',client_name,'date',advisory_date,'hasLinkedWork',has_linked_work)order by id)from page),'[]'::jsonb),
    'nextCursor',case when(select count(*)from matches)>20 then(select id from page order by id desc limit 1)else null end,
    'anchorValid',p_after is null or exists(select 1 from eligible where id=p_after))into answer;
  if p_after is not null and(p_fingerprint is distinct from answer->>'fingerprint'or not(answer->>'anchorValid')::boolean)then
    raise exception 'Destination choices changed'using errcode='40001';end if;
  return answer-'anchorValid';
end $$;

create or replace function public.pro_private_estimate_destination_copy_mutate(p_actor uuid,p_input jsonb)
returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare
  aid uuid;target_id uuid;prior public.pro_private_estimate_destination_copies;
  evidence jsonb;snapshot jsonb;destination jsonb;context jsonb;answer jsonb;line jsonb;pos integer:=0;
  document public.pro_private_estimates;totals jsonb;
begin
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden'using errcode='42501';end if;
  if jsonb_typeof(p_input)is distinct from'object'
    or(select array_agg(key order by key)from jsonb_object_keys(p_input)key)is distinct from array['action','actionId','destination','source','targetEstimateId']
    or p_input->>'action'is distinct from'copy_to_destination'
    or jsonb_typeof(p_input->'actionId')is distinct from'string'
    or jsonb_typeof(p_input->'targetEstimateId')is distinct from'string'
    or jsonb_typeof(p_input->'destination')is distinct from'object'then
    raise exception 'Invalid destination copy'using errcode='22023';end if;
  aid:=(p_input->>'actionId')::uuid;target_id:=(p_input->>'targetEstimateId')::uuid;destination:=p_input->'destination';
  if aid is null or target_id is null
    or(select array_agg(key order by key)from jsonb_object_keys(destination)key)is distinct from array['clientFingerprint','clientId','source']
    or jsonb_typeof(destination->'clientId')is distinct from'string'or length(destination->>'clientId')not between 1 and 160
    or jsonb_typeof(destination->'clientFingerprint')is distinct from'string'
    or not coalesce(destination->>'clientFingerprint'~'^[a-f0-9]{32}$',false)
    or jsonb_typeof(destination->'source')not in('null','object')then
    raise exception 'Invalid destination snapshot'using errcode='22023';end if;
  if destination->'source'<>'null'::jsonb then
    if destination->'source'->>'kind'='manual'then
      if(select array_agg(key order by key)from jsonb_object_keys(destination->'source')key)is distinct from array['id','kind','revision']
        or jsonb_typeof(destination->'source'->'revision')is distinct from'number'
        or not coalesce(destination->'source'->>'revision'~'^[0-9]{1,10}$',false)
        or(destination->'source'->>'revision')::numeric not between 1 and 2147483647 then raise exception 'Invalid opportunity destination'using errcode='22023';end if;
    elsif destination->'source'->>'kind'='work'then
      if(select array_agg(key order by key)from jsonb_object_keys(destination->'source')key)is distinct from array['fingerprint','id','kind']
        or jsonb_typeof(destination->'source'->'fingerprint')is distinct from'string'
        or not coalesce(destination->'source'->>'fingerprint'~'^[a-f0-9]{32}$',false)then raise exception 'Invalid work destination'using errcode='22023';end if;
    else raise exception 'Invalid destination origin'using errcode='22023';end if;
    if jsonb_typeof(destination->'source'->'id')is distinct from'string'or length(destination->'source'->>'id')not between 1 and 160 then
      raise exception 'Invalid destination identity'using errcode='22023';end if;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
  perform pg_advisory_xact_lock(hashtextextended('pro-private-estimate-action:'||p_actor::text||':'||aid::text,0));
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden'using errcode='42501';end if;
  select * into prior from public.pro_private_estimate_destination_copies c where c.actor_id=p_actor and c.action_id=aid;
  if found then
    if prior.input is distinct from p_input then raise exception 'Destination copy action reused'using errcode='40001';end if;
    if not exists(select 1 from public.pro_private_estimates where owner_id=p_actor and id=prior.target_estimate_id)then
      raise exception 'Owned copy unavailable'using errcode='42501';end if;
    return prior.result;
  end if;
  if exists(select 1 from public.pro_private_estimate_actions where actor_id=p_actor and action_id=aid)
    or exists(select 1 from public.pro_private_estimate_history where owner_id=p_actor and action_id=aid)
    or exists(select 1 from public.pro_private_estimates where owner_id=p_actor and id=target_id)then
    raise exception 'Copy action or target already exists'using errcode='40001';end if;
  if p_input->'source'->>'kind'='draft'then
    perform 1 from public.pro_private_estimates where owner_id=p_actor and id=(p_input->'source'->>'estimateId')::uuid for share nowait;
  end if;
  evidence:=public.pro_private_estimate_destination_copy_source(p_actor,p_input->'source');snapshot:=evidence->'estimate';
  if snapshot->>'id'=target_id::text then raise exception 'Copy needs a new document'using errcode='40001';end if;
  if destination->'source'->>'kind'='manual'then
    perform 1 from public.pro_lead_center_records where owner_id=p_actor and kind='manual'and id=(destination->'source'->>'id')::uuid for share nowait;
  elsif destination->'source'->>'kind'='work'then
    perform 1 from public.pro_work where user_id=p_actor and id=destination->'source'->>'id'for share nowait;
  end if;
  perform 1 from public.pro_clients where user_id=p_actor and id=destination->>'clientId'for share nowait;
  context:=public.pro_private_estimate_destination_copy_context(p_actor,destination->>'clientId',destination->'source'->>'kind',destination->'source'->>'id');
  if context->'client'->>'id'is distinct from destination->>'clientId'
    or context->'clientFingerprint'is distinct from destination->'clientFingerprint'
    or context->'source'is distinct from destination->'source'then
    raise exception 'Reviewed destination changed'using errcode='40001';end if;
  totals:=public.pro_private_estimate_totals(snapshot->'lines');
  if totals is distinct from jsonb_build_object('subtotalCents',snapshot->'subtotalCents',
    'discountCents',snapshot->'discountCents','taxCents',snapshot->'taxCents','totalCents',snapshot->'totalCents')then
    raise exception 'Saved source totals changed'using errcode='40001';end if;
  insert into public.pro_private_estimates(owner_id,id,client_id,client_snapshot,source,issuer,title,notes,currency,valid_until,
    subtotal_cents,discount_cents,tax_cents,total_cents,revision,archived,created_at,updated_at)
    values(p_actor,target_id,destination->>'clientId',context->'client',context->'source',snapshot->'issuer',
      snapshot->>'title',snapshot->>'notes',snapshot->>'currency',(snapshot->>'validUntil')::date,
      (snapshot->>'subtotalCents')::bigint,(snapshot->>'discountCents')::bigint,(snapshot->>'taxCents')::bigint,
      (snapshot->>'totalCents')::bigint,1,false,clock_timestamp(),clock_timestamp())returning * into document;
  for line in select value from jsonb_array_elements(snapshot->'lines')loop
    pos:=pos+1;insert into public.pro_private_estimate_items values(p_actor,target_id,(line->>'id')::uuid,pos,line);
  end loop;
  answer:=jsonb_build_object('action','copy_to_destination','source',evidence->'source','estimate',public.pro_private_estimate_json(document));
  insert into public.pro_private_estimate_history(owner_id,estimate_id,action_id,action,before_estimate,after_estimate)
    values(p_actor,target_id,aid,'duplicate',snapshot,answer->'estimate');
  insert into public.pro_private_estimate_destination_copies(actor_id,action_id,target_estimate_id,source_kind,source_estimate_id,source_snapshot,destination_snapshot,input,result)
    values(p_actor,aid,target_id,p_input->'source'->>'kind',(snapshot->>'id')::uuid,snapshot,context,p_input,answer);
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden'using errcode='42501';end if;
  return answer;
exception when lock_not_available then
  raise exception 'Source or destination is busy; review and retry'using errcode='40001';
end $$;

create or replace function public.pro_private_estimate_destination_copy_read(p_actor uuid,p_action uuid)
returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare receipt public.pro_private_estimate_destination_copies;
begin
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)then raise exception 'Forbidden'using errcode='42501';end if;
  select * into receipt from public.pro_private_estimate_destination_copies where actor_id=p_actor and action_id=p_action;
  if not found then return jsonb_build_object('receipt',null);end if;
  if not exists(select 1 from public.pro_private_estimates where owner_id=p_actor and id=receipt.target_estimate_id)then
    raise exception 'Owned copy unavailable'using errcode='42501';end if;
  return jsonb_build_object('receipt',jsonb_build_object('input',receipt.input,'result',receipt.result));
end $$;

create or replace function public.pro_private_estimate_destination_copy_immutable()
returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin
  if tg_op='DELETE'and not exists(select 1 from public.profiles where id=old.actor_id)then return old;end if;
  raise exception 'Immutable destination copy provenance'using errcode='23514';
end $$;
drop trigger if exists pro_private_estimate_destination_copy_immutable on public.pro_private_estimate_destination_copies;
create trigger pro_private_estimate_destination_copy_immutable before update or delete on public.pro_private_estimate_destination_copies
  for each row execute function public.pro_private_estimate_destination_copy_immutable();
alter table public.pro_private_estimate_destination_copies enable row level security;
revoke all on public.pro_private_estimate_destination_copies from public,anon,authenticated;
grant all on public.pro_private_estimate_destination_copies to service_role;
do $$declare f record;begin
  for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public'and p.proname like'pro_private_estimate_destination_copy_%'loop
    execute format('revoke all on function %s from public,anon,authenticated',f.signature);
    execute format('grant execute on function %s to service_role',f.signature);
  end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== client-dashboard-local.sql =====
-- LOCAL PRO ONLY. Owner-configured customer view for one job (Houzz-style
-- "Client Dashboard" customization, family 33). Presentation preferences only:
-- hiding a section is NOT an access revocation. Shared versions, files and
-- publications keep their own permission checks and remain unchanged.
-- No changes to work, request, update, daily log, file, change or delivery rows.
begin;
create table if not exists public.pro_client_dashboards(
 owner_id uuid not null references public.profiles(id) on delete cascade,work_id text not null,
 show_updates boolean not null default true,show_daily_logs boolean not null default true,show_files boolean not null default true,
 welcome_text text check(welcome_text is null or length(btrim(welcome_text)) between 1 and 1000),
 revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,work_id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
-- Family 75 (allowances): opt-in section, off by default. Existing rows keep the
-- previous customer view because the column defaults to false; reapplicable.
alter table public.pro_client_dashboards add column if not exists show_allowances boolean not null default false;
-- Family 62 (selections): opt-in section, off by default; same compatibility rule as allowances.
alter table public.pro_client_dashboards add column if not exists show_selections boolean not null default false;
-- Families 13/15 (schedule and punch list): opt-in sections, off by default; same compatibility rule.
alter table public.pro_client_dashboards add column if not exists show_schedule boolean not null default false;
alter table public.pro_client_dashboards add column if not exists show_punchlist boolean not null default false;
-- Row 40 (contracts): opt-in section, off by default; same compatibility rule.
alter table public.pro_client_dashboards add column if not exists show_contracts boolean not null default false;
-- Row 61 (idea boards): opt-in section, off by default; same compatibility rule.
alter table public.pro_client_dashboards add column if not exists show_mood_boards boolean not null default false;
create table if not exists public.pro_client_dashboard_history(
 owner_id uuid not null,work_id text not null,action_id uuid not null,before_settings jsonb,after_settings jsonb not null,at timestamptz not null default now(),
 primary key(owner_id,action_id),foreign key(owner_id,work_id) references public.pro_client_dashboards(owner_id,work_id) on delete cascade
);
create index if not exists pro_client_dashboard_history_page on public.pro_client_dashboard_history(owner_id,work_id,((after_settings->>'revision')::integer) desc);
create table if not exists public.pro_client_dashboard_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id)
);
-- Defaults (revision 0) reproduce the customer view that existed before this module.
create or replace function public.pro_client_dashboard_settings_json(p_work text,p_row public.pro_client_dashboards) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('workId',p_work,'showUpdates',coalesce(p_row.show_updates,true),'showDailyLogs',coalesce(p_row.show_daily_logs,true),
 'showFiles',coalesce(p_row.show_files,true),'showAllowances',coalesce(p_row.show_allowances,false),'showSelections',coalesce(p_row.show_selections,false),'showSchedule',coalesce(p_row.show_schedule,false),'showPunchlist',coalesce(p_row.show_punchlist,false),'showContracts',coalesce(p_row.show_contracts,false),'showMoodBoards',coalesce(p_row.show_mood_boards,false),'welcomeText',p_row.welcome_text,'revision',coalesce(p_row.revision,0),'updatedAt',p_row.updated_at);
$$;
create or replace function public.pro_client_dashboard_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare settings public.pro_client_dashboards;hist jsonb;recipient_name text;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid dashboard query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 select * into settings from public.pro_client_dashboards where owner_id=p_actor and work_id=p_work;
 select ar.client_name into recipient_name from public.pro_appointment_requests ar join public.profiles c on c.id=ar.client_user_id
  where ar.owner_id=p_actor and ar.work_id=p_work and ar.status in('confirmed','completed') and not coalesce(c.is_disabled,false)
  order by ar.updated_at desc,ar.id desc limit 1; -- deterministic: most recently updated confirmed request
 select coalesce(jsonb_agg(x.content order by x.revision desc),'[]'::jsonb) into hist from (
  select (h.after_settings->>'revision')::integer as revision,jsonb_build_object('actionId',h.action_id,'at',h.at,'before',h.before_settings,'after',h.after_settings) as content
  from public.pro_client_dashboard_history h where h.owner_id=p_actor and h.work_id=p_work order by (h.after_settings->>'revision')::integer desc limit 20
 ) x;
 return jsonb_build_object('settings',public.pro_client_dashboard_settings_json(p_work,settings),'history',hist,'recipientName',recipient_name);
end $$;
create or replace function public.pro_client_dashboard_client_read(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare owner uuid;wid text;settings public.pro_client_dashboards;req_status text;
begin
 -- Same audience as the shared readers: the linked customer of this request only.
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select owner_id,work_id,status into owner,wid,req_status from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null;
 if not found then return null;end if;
 select * into settings from public.pro_client_dashboards where owner_id=owner and work_id=wid;
 -- The welcome message is live owner text, not a shared version: only the linked
 -- customer the owner editor names (confirmed/completed request) receives it.
 return jsonb_build_object('showUpdates',coalesce(settings.show_updates,true),'showDailyLogs',coalesce(settings.show_daily_logs,true),
  'showFiles',coalesce(settings.show_files,true),'welcomeText',case when req_status in('confirmed','completed') then settings.welcome_text end);
end $$;
create or replace function public.pro_client_dashboard_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare wid text;aid uuid;rev integer;keys text[];receipt public.pro_client_dashboard_actions;settings public.pro_client_dashboards;before_json jsonb;after_json jsonb;result jsonb;welcome text;allowances boolean;selections boolean;schedule boolean;punchlist boolean;contracts boolean;moodboards boolean;base_keys text[];
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid dashboard' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 -- showAllowances and showSelections are optional so older clients keep working; when absent the stored value is kept.
 select array_agg(k order by k) into base_keys from unnest(keys) k where k not in('showAllowances','showSelections','showSchedule','showContracts','showPunchlist','showMoodBoards');
 if base_keys is distinct from array['actionId','revision','showDailyLogs','showFiles','showUpdates','welcomeText','workId']
 or (p_input?'showAllowances' and jsonb_typeof(p_input->'showAllowances') is distinct from 'boolean')
 or (p_input?'showSelections' and jsonb_typeof(p_input->'showSelections') is distinct from 'boolean')
 or (p_input?'showSchedule' and jsonb_typeof(p_input->'showSchedule') is distinct from 'boolean')
 or (p_input?'showPunchlist' and jsonb_typeof(p_input->'showPunchlist') is distinct from 'boolean')
 or (p_input?'showContracts' and jsonb_typeof(p_input->'showContracts') is distinct from 'boolean')
 or (p_input?'showMoodBoards' and jsonb_typeof(p_input->'showMoodBoards') is distinct from 'boolean')
 or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string'
 or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false)
 or jsonb_typeof(p_input->'showUpdates') is distinct from 'boolean' or jsonb_typeof(p_input->'showDailyLogs') is distinct from 'boolean'
 or jsonb_typeof(p_input->'showFiles') is distinct from 'boolean' or jsonb_typeof(p_input->'welcomeText') not in('string','null') then raise exception 'Invalid dashboard fields' using errcode='22023';end if;
 if (p_input->>'revision')::numeric>2147483646 then raise exception 'Invalid revision' using errcode='22023';end if;
 wid:=p_input->>'workId';aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 if length(wid) not between 1 and 160 then raise exception 'Invalid dashboard identity' using errcode='22023';end if;
 welcome:=nullif(btrim(coalesce(p_input->>'welcomeText','')),'');
 if welcome is not null and length(welcome)>1000 then raise exception 'Invalid welcome text' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-client-dashboard-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_client_dashboard_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-client-dashboard:'||p_actor::text||':'||wid,0));
 perform 1 from public.pro_work where user_id=p_actor and id=wid for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 select * into settings from public.pro_client_dashboards where owner_id=p_actor and work_id=wid for update;
 if not found then
  if rev<>0 then raise exception 'Dashboard changed' using errcode='40001';end if;
  before_json:=null;allowances:=coalesce((p_input->>'showAllowances')::boolean,false);selections:=coalesce((p_input->>'showSelections')::boolean,false);
  schedule:=coalesce((p_input->>'showSchedule')::boolean,false);punchlist:=coalesce((p_input->>'showPunchlist')::boolean,false);contracts:=coalesce((p_input->>'showContracts')::boolean,false);moodboards:=coalesce((p_input->>'showMoodBoards')::boolean,false);
  insert into public.pro_client_dashboards(owner_id,work_id,show_updates,show_daily_logs,show_files,show_allowances,show_selections,show_schedule,show_contracts,show_punchlist,show_mood_boards,welcome_text)
   values(p_actor,wid,(p_input->>'showUpdates')::boolean,(p_input->>'showDailyLogs')::boolean,(p_input->>'showFiles')::boolean,allowances,selections,schedule,contracts,punchlist,moodboards,welcome) returning * into settings;
 else
  if rev<>settings.revision then raise exception 'Dashboard changed' using errcode='40001';end if;
  before_json:=public.pro_client_dashboard_settings_json(wid,settings);allowances:=coalesce((p_input->>'showAllowances')::boolean,settings.show_allowances);selections:=coalesce((p_input->>'showSelections')::boolean,settings.show_selections);
  schedule:=coalesce((p_input->>'showSchedule')::boolean,settings.show_schedule);punchlist:=coalesce((p_input->>'showPunchlist')::boolean,settings.show_punchlist);contracts:=coalesce((p_input->>'showContracts')::boolean,settings.show_contracts);moodboards:=coalesce((p_input->>'showMoodBoards')::boolean,settings.show_mood_boards);
  if settings.show_allowances=allowances and settings.show_selections=selections and settings.show_schedule=schedule and settings.show_punchlist=punchlist and settings.show_contracts=contracts and settings.show_mood_boards=moodboards and settings.show_updates=(p_input->>'showUpdates')::boolean and settings.show_daily_logs=(p_input->>'showDailyLogs')::boolean
   and settings.show_files=(p_input->>'showFiles')::boolean and settings.welcome_text is not distinct from welcome then raise exception 'No dashboard changes' using errcode='22023';end if;
  update public.pro_client_dashboards set show_updates=(p_input->>'showUpdates')::boolean,show_daily_logs=(p_input->>'showDailyLogs')::boolean,
   show_files=(p_input->>'showFiles')::boolean,show_allowances=allowances,show_selections=selections,show_schedule=schedule,show_contracts=contracts,show_punchlist=punchlist,show_mood_boards=moodboards,welcome_text=welcome,revision=revision+1,updated_at=now() where owner_id=p_actor and work_id=wid returning * into settings;
 end if;
 after_json:=public.pro_client_dashboard_settings_json(wid,settings);result:=jsonb_build_object('settings',after_json);
 insert into public.pro_client_dashboard_history(owner_id,work_id,action_id,before_settings,after_settings) values(p_actor,wid,aid,before_json,after_json);
 insert into public.pro_client_dashboard_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;
create or replace function public.pro_client_dashboard_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Dashboard history and receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_client_dashboard_history_immutable on public.pro_client_dashboard_history;
create trigger pro_client_dashboard_history_immutable before update on public.pro_client_dashboard_history for each row execute function public.pro_client_dashboard_immutable();
drop trigger if exists pro_client_dashboard_action_immutable on public.pro_client_dashboard_actions;
create trigger pro_client_dashboard_action_immutable before update on public.pro_client_dashboard_actions for each row execute function public.pro_client_dashboard_immutable();
alter table public.pro_client_dashboards enable row level security;
alter table public.pro_client_dashboard_history enable row level security;
alter table public.pro_client_dashboard_actions enable row level security;
revoke all on public.pro_client_dashboards,public.pro_client_dashboard_history,public.pro_client_dashboard_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_client_dashboards,public.pro_client_dashboard_history,public.pro_client_dashboard_actions to service_role;
revoke all on function public.pro_client_dashboard_settings_json(text,public.pro_client_dashboards),public.pro_client_dashboard_read(uuid,text),public.pro_client_dashboard_client_read(uuid,uuid),public.pro_client_dashboard_mutate(uuid,jsonb),public.pro_client_dashboard_immutable() from public,anon,authenticated;
grant execute on function public.pro_client_dashboard_settings_json(text,public.pro_client_dashboards),public.pro_client_dashboard_read(uuid,text),public.pro_client_dashboard_client_read(uuid,uuid),public.pro_client_dashboard_mutate(uuid,jsonb) to service_role;
commit;

-- ===== projects-local.sql =====
-- LOCAL PRO ONLY. Read-only "Projects" hub over existing jobs (pro_work).
-- No new tables and no writes. The status is derived from the existing job
-- fields; it never changes them. Ordered newest first by the stable identity
-- position, because pro_work has no creation timestamp (none is invented).
begin;
create or replace function public.pro_project_status(p_work public.pro_work) returns text
language sql immutable security invoker set search_path=public,pg_temp as $$
 select case when coalesce(p_work.cancelled,false) then 'cancelled' when p_work.stage='completed' then 'completed'
  when p_work.stage='scheduled' and p_work."start"<>'' then 'in_progress' else 'open' end;
$$;
create or replace function public.pro_projects_page(p_actor uuid,p_status text default 'active',p_search text default '',p_after bigint default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;next_cursor bigint;counts jsonb;needle text;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_status is null or p_status not in('active','open','in_progress','completed','cancelled','all') or p_search is null or length(p_search)>160 or p_after is not null and p_after<1 then
  raise exception 'Invalid project query' using errcode='22023';end if;
 needle:=nullif(btrim(p_search),'');
 select jsonb_build_object('open',count(*) filter(where s='open'),'in_progress',count(*) filter(where s='in_progress'),'completed',count(*) filter(where s='completed'),'cancelled',count(*) filter(where s='cancelled'),'all',count(*))
  into counts from (select public.pro_project_status(w) s from public.pro_work w where w.user_id=p_actor) x;
 select coalesce(jsonb_agg(x.content order by x.position desc),'[]'::jsonb) into items from (
  select w.position,jsonb_build_object('id',w.id,'name',w.service,'client',w.client,'clientId',w."clientId",'status',public.pro_project_status(w),
   'start',nullif(w."start",''),'end',nullif(w."end",''),'hasQuote',w."quoteId" is not null or w."externalQuoteId" is not null,
   'linkedCustomer',exists(select 1 from public.pro_appointment_requests r join public.profiles c on c.id=r.client_user_id
     where r.owner_id=w.user_id and r.work_id=w.id and r.status in('confirmed','completed') and not coalesce(c.is_disabled,false)),
   'customView',exists(select 1 from public.pro_client_dashboards d where d.owner_id=w.user_id and d.work_id=w.id)) as content
  from public.pro_work w
  where w.user_id=p_actor and (p_after is null or w.position<p_after)
   and (p_status='all' or p_status='active' and public.pro_project_status(w) in('open','in_progress') or public.pro_project_status(w)=p_status)
   and (needle is null or strpos(lower(w.service),lower(needle))>0 or strpos(lower(w.client),lower(needle))>0)
  order by w.position desc limit 21
 ) x;
 if jsonb_array_length(items)>20 then
  select w.position into next_cursor from public.pro_work w where w.user_id=p_actor and w.id=items->19->>'id';
  items:=items-20;
 end if;
 return jsonb_build_object('items',items,'nextCursor',next_cursor,'counts',counts);
end $$;
revoke all on function public.pro_project_status(public.pro_work),public.pro_projects_page(uuid,text,text,bigint) from public,anon,authenticated;
grant execute on function public.pro_project_status(public.pro_work),public.pro_projects_page(uuid,text,text,bigint) to service_role;
commit;

-- ===== project-planning-local.sql =====
-- LOCAL PRO ONLY. Project "Planning" -> estimates of one job (pro_work).
-- Read-only: no new tables, no writes and no inferred links. An estimate belongs
-- to the project only through an EXISTING stored link:
--   1. its immutable source is this job (source.kind='work', source.id=job id);
--   2. one of its accepted publications is this job's agreement
--      (pro_private_estimate_work_agreements.work_id);
--   3. its source is a manual lead that was converted into this job
--      (pro_manual_lead_works.work_id).
-- "client" lists active estimates of the job's customer that have none of those
-- links to ANY job, so another project's estimate never appears here.
-- Archived estimates are excluded, as in the commercial list.
begin;
create or replace function public.pro_project_estimate_rows(p_actor uuid,p_work public.pro_work)
returns table(estimate_id uuid,relation text,created_at timestamptz)
language sql stable security invoker set search_path=public,pg_temp as $$
 select x.id,x.relation,x.created_at from (
  select d.id,d.created_at,case
   when (d.source->>'kind'='work' and d.source->>'id'=p_work.id)
    or exists(select 1 from public.pro_private_estimate_work_agreements a where a.owner_id=p_actor and a.estimate_id=d.id and a.work_id=p_work.id)
    or (d.source->>'kind'='manual' and exists(select 1 from public.pro_manual_lead_works m where m.owner_id=p_actor and m.lead_id::text=d.source->>'id' and m.work_id_text=p_work.id))
    -- Launch fix I1 (2026-11-17): a quote shared to the customer account linked to THIS job belongs to the job
    -- (its acceptance continues into it, quote-circuit-local.sql), so it counts in the job's quotes and next steps.
    or exists(select 1 from public.pro_private_estimate_publication_recipients b join public.pro_appointment_requests r on r.owner_id=b.owner_id and r.id::text=b.proof->>'requestId' and r.client_user_id=b.recipient_id
     where b.owner_id=p_actor and b.estimate_id=d.id and b.proof->>'kind'='linked' and r.work_id=p_work.id)
   then 'project'
   when d.client_id=p_work."clientId"
    and coalesce(d.source->>'kind','')<>'work'
    and not exists(select 1 from public.pro_private_estimate_work_agreements a where a.owner_id=p_actor and a.estimate_id=d.id)
    and not (d.source->>'kind'='manual' and exists(select 1 from public.pro_manual_lead_works m where m.owner_id=p_actor and m.lead_id::text=d.source->>'id'))
   then 'client' end relation
  from public.pro_private_estimates d where d.owner_id=p_actor and not d.archived
 ) x where x.relation is not null;
$$;
create or replace function public.pro_project_estimates_page(p_actor uuid,p_work text,p_scope text default 'project',p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w public.pro_work;items jsonb;next_cursor uuid;counts jsonb;cursor_time timestamptz;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or p_scope is null or p_scope not in('project','client') then raise exception 'Invalid project estimate query' using errcode='22023';end if;
 select * into w from public.pro_work where user_id=p_actor and id=p_work;
 if not found then raise exception 'Project not found' using errcode='P0002';end if;
 select jsonb_build_object('project',count(*) filter(where r.relation='project'),'client',count(*) filter(where r.relation='client')) into counts from public.pro_project_estimate_rows(p_actor,w) r;
 if p_after is not null then
  select r.created_at into cursor_time from public.pro_project_estimate_rows(p_actor,w) r where r.estimate_id=p_after and r.relation=p_scope;
  if not found then raise exception 'Project estimate cursor changed' using errcode='40001';end if;
 end if;
 with picked as(
  select r.estimate_id,r.created_at from public.pro_project_estimate_rows(p_actor,w) r
  where r.relation=p_scope and (p_after is null or (r.created_at,r.estimate_id)<(cursor_time,p_after))
  order by r.created_at desc,r.estimate_id desc limit 21
 ),latest as(
  select distinct on(v.estimate_id) v.estimate_id,v.id,v.version,v.estimate_revision,v.content
  from public.pro_private_estimate_publications v join picked p on p.estimate_id=v.estimate_id
  where v.owner_id=p_actor order by v.estimate_id,v.version desc
 )
 select coalesce(jsonb_agg(jsonb_build_object(
   'id',d.id,'relation',p_scope,'title',coalesce(v.content->>'title',d.title),
   'clientId',d.client_id,'clientName',coalesce(v.content->'customer'->>'name',d.client_snapshot->>'name',''),
   'status',case when v.id is null then 'draft' when s.status in('awaiting_claim','shared','changes_requested') then 'sent' when s.status in('withdrawn','superseded') then 'withdrawn' else s.status end,
   'publicationStatus',s.status,
   'currency',coalesce(v.content->>'currency',d.currency),
   'totalCents',coalesce((v.content->>'totalCents')::bigint,d.total_cents),
   'revision',d.revision,'unpublishedChanges',v.id is not null and v.estimate_revision<d.revision,
   'agreement',exists(select 1 from public.pro_private_estimate_work_agreements a where a.owner_id=p_actor and a.estimate_id=d.id and a.work_id=w.id),
   'sourceKind',d.source->>'kind','createdAt',d.created_at,'updatedAt',d.updated_at
  ) order by p.created_at desc,p.estimate_id desc),'[]'::jsonb) into items
 from picked p join public.pro_private_estimates d on d.owner_id=p_actor and d.id=p.estimate_id
 left join latest v on v.estimate_id=d.id
 left join public.pro_private_estimate_publication_states s on s.publication_id=v.id;
 if jsonb_array_length(items)>20 then next_cursor:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('workId',w.id,'clientId',w."clientId",'scope',p_scope,'items',items,'nextCursor',next_cursor,'counts',counts);
end $$;
revoke all on function public.pro_project_estimate_rows(uuid,public.pro_work),public.pro_project_estimates_page(uuid,text,text,uuid) from public,anon,authenticated;
grant execute on function public.pro_project_estimate_rows(uuid,public.pro_work),public.pro_project_estimates_page(uuid,text,text,uuid) to service_role;
commit;
notify pgrst, 'reload schema';
